window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_018"]={"n":"张雨","dyn":"元","poems":[{"t":"梧叶儿","f":"曲","c":["移家去，市隐间。","幽事颇相关。","刘商观棋罢，韩康卖药还。","点检绿云鬟。","数不尽、龟溪好山。"]},{"t":"湖州竹枝词","f":"七言绝句","c":["临湖门外是侬家，郎若閒时来吃茶。","黄土筑墙茅盖屋，门前一树紫荆花。"]},{"t":"范以善云林清远馆","f":"七言律诗","c":["华阳范监居幽眇，不到玄窗未易逢。","山气半为湖外雨，松声遥答岭头钟。","尝闻神女骑龙过，亦有仙人控鹤从。","安用乘流三万里，小天元在积金峰。"]},{"t":"八声甘州 舟次垂虹寄玄洲许道民","f":"曲","c":["柳洲冰未浣柰春寒，仙风引归槎。","渺云岑天末，烟江雨外，犹认渔家。","独酌瓦瓯篷底，谁与饭胡麻。","疑听松风响，水宿蒹葭。","天上春愁鹤发，许一庵闲地，坏衲双髽。","笑清狂无赖，痼疾是烟霞。","念葛洪、移居辛苦，甚左郎、容易问丹砂。","凭传语、空山流水，深护桃花。"]},{"t":"凤凰台上忆吹箫 和欧阳彦珍催桂","f":"曲","c":["桂影团团，小山丛底，今年特地收香。","早阵风阵雨，频掩西窗。","一剪辟寒金碎，甚教人、长想容光。","凄凉夜，香篝撤去，孤负华堂。","金菊芙蓉，尽未怕换叶移根，多少思量。","纵素娥老去，肯便相忘。","怪得探芳秋蝶，向翠阴深处回翔。","非迟暮，一枝折得，留待仙郎。"]},{"t":"太常引","f":"曲","c":["莫将西子比西湖。","千古一陶朱。","生怕在楼居。","也用着、风帆短蒲。","银瓶索酒，并刀斫鲙，船背锦模糊。","堤上早传呼。","那个是、烟波钓徒。"]},{"t":"太常引 浴鹄湾有咏写奉易玄","f":"曲","c":["一丛奇石古苔龛。","一半浸挼蓝。","有几许烟岚。","怕鱼鸟、惊人笑谈。","幽幽尺宅，萧萧环堵，佳处要人参。","休看是江南。","似钴鉧、潭西小潭。"]},{"t":"忆秦娥","f":"曲","c":["兰舟小。","沿堤傍着裙腰草。","裙腰草。","年年青翠，几曾枯槁。","渔歌一曲随颠倒。","酒壶早是容情了。","容情了。","肯来清坐，吃茶须好。"]},{"t":"忆秦娥","f":"曲","c":["兰舟小。","一篷也便容身了。","容身了。","几番烟雨，几番昏晓。","出桥三面青山绕。","入城一向红尘扰。","红尘扰。","绿蓑青笠，让渠多少。"]},{"t":"木兰花慢 己未十月十七日寿溪月真人","f":"曲","c":["试瑶台借雪，春意早，满林峦。","笑东老殷勤，能倾家酿，与尽清欢。","曾因求贤把诏，便朗吟、湓浦又庐山。","自爱西湖烟雨，玉鞭分付青鸾。","神仙官府肯容闲。","枢要在玄关。","有溪上金鳌，月中金粟，长驻婴颜。","愿似洪厓橘术，尽千年、游戏向人间。","早晚凤池书到，通明殿上催班。"]},{"t":"木兰花慢 龟溪寄张小山","f":"曲","c":["问出山小草，谁与伴，五湖游。","便忆昔风光，桃花流水，杜若芳洲。","来时洞门无锁，倩鹤群、长绕侍仙楼。","邂逅小山招隐，依然我辈清流。","春愁相恋住余不。","寒拥敝貂裘。","柰雨柳烟花，云帆溪鸟，都在帘钩。","眼前自无俗物，动山心、嫌听鹿呦呦。","猛把石阑干拍，贾胡知为谁留。"]},{"t":"木兰花慢 和马昂夫","f":"曲","c":["想桐君山水，正睡雨，听淋浪。","记短棹曾经，烟村晚渡，石磴飞梁。","无端故人书尺，便梦中、颠倒我衣裳。","此去钓台多少，小山丛桂秋香。","青苍秀色未渠央。","台榭半消亡。","拟招隐羊裘，寻盟鸥社，投老渔乡。","何时扁舟到手，有一襟、风月待平章。","输与浮丘仙伯，九皋声外苍茫。"]},{"t":"木兰花慢 和黄一峰闻筝","f":"曲","c":["尽弹筝仕女，会银甲，骤冰弦。","看蝉影僛僛，莺声历历，鸿阵翩翩。","哀音暮年多感，柰对花、对酒更闻鹃。","却恐乘云飞去，缠头袅住非烟。","乌丝缀谱倩陈玄。","雅调为谁传。","嗟江上峰青，湘皋木落，与挟飞仙。","正须丝竹陶写，尽胜渠、槌拍事枯禅。","莫负金尊皓月，难留锦瑟华年。"]},{"t":"木兰花慢 秋词","f":"曲","c":["看秋容渐好，一番雨，一番凉。","试点检吾家，小山丛桂，金粟都黄。","涛江限他吴越，便胥魂、不似向时狂。","眼底龙飞凤舞，梦中狐啸鸱张。","茫茫今古总堪伤。","歌罢意难忘。","甚老矣稽生，五弦挥手，怕听清商。","渊明平生师友，白衣人、借与我持觞。","若问醉翁年纪，指渠松柏高冈。"]},{"t":"水龙吟 代玄览和东泉学士自寿之作","f":"曲","c":["古来宰相神仙，有谁得似东泉老。","今朝佳宴，杨枝解唱，花枝解笑。","钟鼎山林，同时行辈，故人应少。","问功成身退，何须更学，鸱夷子，烟波渺。","我自深衣独乐，尽从渠、黄尘乌帽。","后来官职清高，一品还他三少。","不须十载光阴，渭水相逢，又入非熊梦了。","到恁时、拂袖逍遥，胜戏十洲三岛。"]},{"t":"水调歌头 为初心真人七帙初度时延祥有赐田之命","f":"曲","c":["瑞霭延真馆，春满瑞真家。","绛县老人年纪，更柰紫髯何。","前日黄华迎赐，赐予青毡旧物，田野总讴歌。","报贶启金箓，笙鹤恰来过。","问蟠桃，花结实，树交柯。","今朝佳气五云，都在牡丹坡。","何物可为公寿，直比心如明月，清镜阅人多。","于此看勋业，铜狄细摩挲。"]},{"t":"水调歌头 盆荷","f":"曲","c":["江湖渺何许，归兴浩无边。","忽闻数声水调，令我意悠然。","莫笑盆池咫尺，移得风烟万顷，来傍小窗前。","稀疏淡红翠，特地向人妍。","华峰头，花十丈，藕如船。","那知此中佳趣，别是一壶天。","倒挽碧筒酾酒，醉卧绿云深处，云影自田田。","梦中呼一叶，散发枕书眠。"]},{"t":"水调歌头 赠都料邵子和还嘉禾","f":"曲","c":["别有梓人传，精艺夺天工。","便使玉人雕琢，妙手略相同。","宝殿网珠窗户，华盖狻猊床座，金碧斗玲珑。","花萼间芝草，细缕一重重。","看挥斤，除鼻垩，运成风。","多少巧心奇思，舞凤更翔龙。","纵使棘端猴小，与刻三年楮叶，难比锦心胸。","快袖吴刚斧，修取广寒宫。"]},{"t":"风入松 寿吴大宗师","f":"曲","c":["羽衣能补舜衣裳。","闲看云忙。","宣文奎画龙珠护，□家山、辉映琳琅。","天上重逢初度，仙韶锡宴非常。","满期人道鲁灵光。","合佩金章。","丹牙修出纤纤月，看年年、玉斧吴刚。","不枉盘根寿栎，要扶宗社灵长。"]},{"t":"东风第一枝","f":"曲","c":["清泪如铅，绿房迎晓，宝阶低拥云叶。","蜻蜓飞上搔头，依前艳香未歇。","西窗暗雨，怪帘低、参差凉月。","正一丛、深倚琅玕，石上只愁磨折。","问瑶草、应怜短发。","曾醉堕、无声腻滑。","羞他金雀钿蝉，高似水仙罗袜。","芳心断绝，谁与赠、湘皋琼玦。","试折花、掷作银桥，看舞素鸾回雪。"]},{"t":"石州慢 和黄一峰秋兴","f":"曲","c":["落日空城禾黍，夜深砧杵才歇。","怪他萝薜絺衣，风露润滋凉浃。","清愁多少，只消目送飞鸿，五弦已是心悲咽。","把酒问青天，又中秋时节。","闻说。","谪仙去后，何人敢拟，酒豪诗杰。","草草山窗，还我旧时明月。","书帷冷落，□□□□□□，闲人闲字偏情热。","孤负楮先生，有一庭红叶。"]},{"t":"如梦令","f":"曲","c":["静默两家茅舍。","特地月明狼藉。","不管候虫吟，高枕北窗清夜。","清夜。","清夜。","凉似樊川水榭。"]},{"t":"如梦令","f":"曲","c":["绿锦峰峦似绣。","曲折一渠冰溜。","中有养疴人，敧枕北窗清昼。","清昼。","清昼。","胡蝶还知梦否。"]},{"t":"如梦令 山中逃热三首","f":"曲","c":["湖外残钟未了。","过岭樵夫恁早。","犬吠又人行，推枕北窗清晓。","清晓。","清晓。","劳动数声啼鸟。"]},{"t":"早春怨 拟白石","f":"曲","c":["盼得春来，春寒春困，陡顿无聊。","半剔残釭，片时春梦，过了元宵。","空山暮暮朝朝。","到此际、无魂可消。","却倚东风，水如衣带，草似裙腰。"]},{"t":"百字令","f":"曲","c":["橙黄橘绿，占一年好景，人间真乐。","玉麈金鳌相对峙，如我视今犹昨。","珍重留侯，招邀黄石，俱赴蟠桃约。","一卮仙酒，得陪三老斟酌。","总道独绾银章，重披宫锦，有自家天爵。","八帙明年身更健，胸次遥天恢廓。","春小花繁，溪清月皎，都付延年药。","洞霄仙侣，更添一个仙鹤。"]},{"t":"百字令 四月四日为王国辅生日作","f":"曲","c":["红莲一舸，向游仙梦里，步虚金阙。","朝罢香烟携满袖，初度玳筵重设。","玉轴琵琶，金瓶芍药，都在春风列。","天然清贵，樵林自爱晴雪。","笑说奉母闲居，吾非巧宦，未信潘郎拙。","戏引鸳雏香径底，好在双珠明月。","锦绣楼台，燕莺帘幕，垂柳青丝结。","金笼放鸽，年年飞絮时节。"]},{"t":"苏武慢 至正八年夏和虞道园","f":"曲","c":["清露晨流，新桐初引，消受北窗凉晓。","经卷熏炉，笔床茶具，长物任他围绕。","老子无情，年光有限，只似木人花鸟。","指凝云、数朵奇峰，曾见汉唐池沼。","还自笑，待老学蟫鱼，金题玉躞，书里便容身了。","阿对泉头，布衣无恙，占断雨苔风筱。","独鹤归迟，西山缺处，掠过乱鸦林表。","舞琴心三叠胎仙，坐到天高月小。"]},{"t":"定风波","f":"曲","c":["漆点方瞳雪覆眉。","鹤巢殿角与云齐。","笑挈蓬莱三百丈。","更向。","白云层外着丹梯。","步障诸峰霜似锦。","借问。","高寒那与世人知。","杨子贤王新有教。","淡染。","高丽绫子制荷衣。"]},{"t":"茅山逢故人 句曲道中送友","f":"曲","c":["山下寒林平楚。","山外云帆烟渚。","不饮如何，吾生如梦，鬓毛如许。","能消几度相逢，遮莫而今归去。","壮士黄金，昔人黄鹤，美人黄土。"]},{"t":"南乡子 题李紫筼山居","f":"曲","c":["午枕托冥搜。","得句栖霞半岭头。","不柰风篁疏雨过，飕飕。","化蝶飞来为少留。","石壁倚清秋。","袖拂烟痕写远游。","信有平生濠濮想，悠悠。","身似潜鱼懒上钩。"]},{"t":"柳梢青 题杨补之墨梅","f":"曲","c":["面目冰霜。","逃禅正派，只让花光。","怪底徐卿，为渠描貌，萦损柔肠。","有谁步屧长廊。","更折竹声中细香。","酒半醒时，雪晴寒夜，月上西窗。"]},{"t":"狮儿词 赋梅次仇山村韵","f":"曲","c":["含香弄粉，便句引、游骑寻芳，城南城北。","别有西村、断港冰澌微绿。","孤山路熟。","伴老鹤、晚先寻宿。","怕冻损、三花两蕊，寒泉幽谷。","几番花阴濯足。","记归来醉卧，雪深平屋。","春梦无凭，鬓底闹蛾争扑。","不如图画，相对展、官奴风竹。","烧黄独。","自听瓶笙调曲。"]},{"t":"贺新郎 戏次仲举韵","f":"曲","c":["金屋书中有。","为钱塘佳丽，待寻欢偶。","记得朝云前日梦，伏事东坡最久。","且不是、郡无官守。","日日湖中公事了，更成围、妓女随车后。","翁两鬓，秃如帚。","老来莫负簪花手。","比佳人难得，灵芝三秀。","此夕灯花何太喜，便用买红缠酒。","催看个、肩舆迎取。","有子平生千万足，看明年、堕地于菟走。","挂冠去，学疏受。"]},{"t":"宴山亭 赋杨梅","f":"曲","c":["鹤顶朱圆，丰肌粟聚，宝叶揉蓝初洗。","亲剪翠柯，远赠筠笼，脉脉红泉流齿。","骨换丹砂，笑尚带、儒酸风味。","谁记。","曾问谱西泠，绿阴青子。","君家几度尊前，摘天上繁星，伴人同醉。","纤手素盘，历乱殷红，浮沉半壶脂水。","珍果同时，惟醉写、来禽青李。","争似。","为越女、吴姬染指。"]},{"t":"浪淘沙令","f":"曲","c":["抛下杖头钱。","取次高眠。","玉梅金缕孟家蝉。","说着钱塘都似梦，懒问游船。","谁信酒垆边。","别有仙缘。","自家天地一陶然。","醉写桃符都不记，明日新年。"]},{"t":"烛影摇红 红梅","f":"曲","c":["休击珊瑚，怕惊幺凤枝头睡。","看花犹自未分明，雪在空阶砌。","步障齐奴故里。","尽一幅、仙人绛袂。","妍丹吮粉，拟觅生绡，芳心难寄。","姑射肌肤，朝霞散入春风髓。","石桥冰酒影娥闲，略约相逢地。","错妒嫣然妩媚。","柰儿家、天寒翠被。","碧桃和露，听彻吹笙，绿珠羞坠。"]},{"t":"望梅花 寿师道真人","f":"曲","c":["何处仙家方丈。","浑连水、隔他尘坱。","放鹤天宽，看云窗小，万幅丹青图障。","凭高望。","笑掣金鳌，人道是、蓬莱顶上。","时问葛陂龙杖。","更准备、雪中鹤氅。","修月吴刚，收书东老，消得百壶春酿。","无尽藏。","莫傲清闲，怕诏起、山中宰相。"]},{"t":"渔父","f":"曲","c":["上钓金鳞不用多。","踏翻船子便高歌。","犹有在，问如何。","问取侬家张志和。"]},{"t":"渔父 赞船子和尚二首","f":"曲","c":["此物由来不可名。","丝纶收去水波平。","长抱膝，可怜生。","谁共蓑衣卧月明。"]},{"t":"朝中措 早春书易玄九曲新居壁","f":"曲","c":["草堂移住古城隈。","堂后水平阶。","要结柴桑邻里，不须鸥鹭惊猜。","行厨竹里，园官菜把，野老山杯。","说与定巢新燕，杏花开了重来。"]},{"t":"摸鱼儿","f":"曲","c":["问凌波、并头私语，夜凉谁共料理。","柔情早被鸳鸯妒，怕击水晶如意。","香旖旎。","待微雨清尘，略为新妆洗。","骚辞漫拟。","搴水末芙蓉，同心轻绝，未说已先醉。","空折损，又堕偷香梦里。","藕丝不断新脆。","吴娃小艇无踪迹，也怪半池萍碎。","还略纪。","是月冷、鸥眠鹭宿曾惊起。","高荷恨倚。","总回首西风，露盘轻泻，清泪似铅水。"]},{"t":"摸鱼儿 和王平轩","f":"曲","c":["看棋枰、一番换局，山中知几朝暮。","旧时王谢堂前燕，都付后人怀古。","胡琴语。","索燕寝凝香，此日天应许。","甘回味苦。","笑老子痴顽，胸中色线，终为衮衣补。","投簪去，正有小山丛桂，归来依旧为主。","春江剩酿番江渌，门外尽多朱屦。","高阳侣。","惯踏醉狂歌，惊起星河鹭。","花枝争舞。","语兰玉阶前，秾纤依约，犹染断缣素。"]},{"t":"满江红 开元斗室落成，玄览真人命名得月轩","f":"曲","c":["笑向桃花，又一番、玄都春色。","彷佛记、主家阴洞，不多陈迹。","竹里棋枰憎乌污，林间鹤语无人识。","怪东风、迟暮却归来，庞眉客。","沟水涨，云充斥。","环堵隘，花狼藉。","似石鱼湖小，酒船宽窄。","庭下已生书带草，旁人错认扬雄宅。","问青天、明月落谁家，无心得。"]},{"t":"满江红 玉簪次班彦功韵","f":"曲","c":["玉导纤长，顿化作、云英香荚。","风弄影、录鬟撩乱，搔头斜插。","璞小还思钗燕并，丛幽略比蕉心狭。","看柔须、点缀半开时，微烘蜡。","冰箸瘦，琼枝滑。","芳径底，谁偷掐。","怕夜凉消得，锦围红匝。","鹅管不禁仙露重，蜜脾剩借清香发。","待使君、绝妙好词成，须弹压。"]},{"t":"满庭芳 重九次赵侯韵","f":"曲","c":["湖曲荒烟，石林斜日，笛声凄断山阳。","孤怀无托，只用醉为乡。","回首西风黄落，尽输他、松桧青苍。","相思处，书题新橘，还待满林霜。","人生难会合，良辰孤负，把菊传觞。","便三人对月，独自清狂。","正为跫音空谷，天远近、鸿鹄高翔。","空追和，阳春一曲，聊代紫萸囊。"]},{"t":"瑶花慢 赋雪次仇山村韵","f":"曲","c":["筛冰为雾，屑玉成尘，借阿姨风力。","千岩竞秀，怎一夜、换作连城之璧。","先生闭户，怪短日、寒催驹隙。","想平沙鸿爪成行，□似醉时书迹。","未随埋没双尖，便淡扫蛾眉，与斗颜色。","裁诗白战，驴背上、驮取灞桥吟客。","捻须自笑，尽未让、诸峰头白。","看洗出宫柳梢头，已借淡黄涂额。"]},{"t":"蝶恋花","f":"曲","c":["雨馆幽人朝睡美。","好趁春晴，茶灶随行李。","九朵芙蓉青似洗。","天河一夜增新水。","相送殷勤烦主礼。","燕子无情，不管帆樯起。","错恨分风三十里。","清明小住为佳耳。"]},{"t":"蝶恋花 次疏翁冬至韵","f":"曲","c":["空谷天寒殊慰藉。","半幅瑶华，唤得春回也。","金马玉堂犹传舍。","嵩云颍水风流夜。","驰骋庄骚凌鲍谢。","昔日忘年，解后鸿濛野。","愁绝朱弦谁为写。","高情那复如疏者。"]},{"t":"蝶恋花 新柳","f":"曲","c":["谁道鹅儿黄似酒。","对酒新鹅，得似垂丝柳。","松粉泥金初染就。","年年春雪消时候。","一缕柔情能断否。","雨重烟轻，无力萦窗牖。","试看溪南阴十亩。","落花都聚红云帚。"]},{"t":"踏莎行","f":"曲","c":["春梦还山，药罗岩上。","觉来便觉身无恙。","不知引入市尘壶，丹瓢犹挂苍龙杖。","一脉清凉，三关调畅。","□□更展沧溟量。","还将底事谢先生，山中百斛丹泉酿。"]},{"t":"踏莎行","f":"曲","c":["玉镜台前，看花如雾。","交柯接叶纷无数。","春寒约住柳丝圈，月明染下方诸露。","庐阜神游，湘皋微步。","玉奴老去羞樊素。","韩郎解比影娥池，倩谁摘出香奁句。"]},{"t":"踏莎行 为朱德辉送医僧道二首 其一","f":"曲","c":["龙树名方，阿师偏得。","参苓药笼真奇特。","闲身偶尔病魔侵，几番劳动黄金锡。","灌溉三田，平和百脉。","只消甘露杨枝滴。","八荒寿域太平时，大家都藉慈悲力。"]},{"t":"鹧鸪天 赠医士沈德诚","f":"曲","c":["东老传家道气浓。","榴皮壁上有仙踪。","耳孙阴德如何限，都在参苓药笼中。","无贵贱，有穷通。","活人心事契苍穹。","吾家昆弟能无恙，须藉全生一匕功。"]},{"t":"东汉高士咏十四首 其一 刘翊","f":"五言绝句","c":["子相足周旋，破此家产丰。","阴功谁为书，得来华阳中。"]},{"t":"东汉高士咏十四首 其二 封君达","f":"五言绝句","c":["入山服黄连，还乡骑青牛。","借得五岳图，□去三千秋。"]},{"t":"东汉高士咏十四首 其三 梁鸿","f":"五言绝句","c":["侯光与德耀，布衣心耿耿。","长夜五噫歌，谁念空山冷。"]},{"t":"东汉高士咏十四首 其四 严光","f":"五言绝句","c":["难与助为理，聊复共偃卧。","文叔迫我甚，客星犯帝座。"]},{"t":"东汉高士咏十四首 其五 左慈","f":"五言绝句","c":["老瞒实雄猜，乃忌仙者徒。","鲈鱼既可鲙，蜀姜不可无。"]},{"t":"东汉高士咏十四首 其六 向长","f":"五言绝句","c":["贵诚不如贱，富诚不如贫。","自无子平易，孰悟损益因。"]},{"t":"东汉高士咏十四首 其七 费长房","f":"五言绝句","c":["赠行青竹杖，壶中有馀地。","如何一升酒，尽日登楼醉。"]},{"t":"东汉高士咏十四首 其八 范丹","f":"五言绝句","c":["破甑久生尘，短衣不掩骭。","还渠一斛麦，所拾已杂半。"]},{"t":"东汉高士咏十四首 其九 庞德公","f":"五言绝句","c":["卧龙拜床下，刘表安能屈。","照见采药踪，犹遗鹿门月。"]},{"t":"东汉高士咏十四首 其十 蓟子训","f":"五言绝句","c":["欲追蓟先生，白云迷其方。","驴鞭不可执，寿与铜狄长。"]},{"t":"东汉高士咏十四首 其十一 王乔","f":"五言绝句","c":["吹笙古仙人，政要玉棺埋。","借问双飞凫，何时离县斋。"]},{"t":"东汉高士咏十四首 其十二 韩康","f":"五言绝句","c":["公是伯休那，卖药价不二。","却问夺牛翁，徵君当过未。"]},{"t":"东汉高士咏十四首 其十三 矫慎","f":"五言绝句","c":["养寿慕松乔，洁已配箕颍。","穴居七十年，娶妻终不肯。"]},{"t":"东汉高士咏十四首 其十四 法真","f":"五言绝句","c":["逃名名我随，避名名我追。","去去南北山，与世从此辞。"]},{"t":"奚官洗马图","f":"五言绝句","c":["曾侍赤墀东，天池看浴龙。","晚凉湖上梦，犹立柳阴中。"]},{"t":"明皇按乐图","f":"五言绝句","c":["髯伶识乐句，我信曲有误。","月白商声多，尘起渔阳戍。"]},{"t":"古意","f":"五言绝句","c":["吴绫光纚纚，织成鲸掉尾。","美人不敢裁，恐触波浪起。"]},{"t":"夜思","f":"五言绝句","c":["空山嘈夜雨，幽人坐惆怅。","今夕楚涧泉，明日秦淮浪。"]},{"t":"玄洲倡和十首 其一 菌山","f":"五言绝句","c":["灵邱状三秀，紫云覆其颠。","易我朝生质，阅彼大椿年。"]},{"t":"玄洲倡和十首 其二 罗姑洞","f":"五言绝句","c":["九疑得道女，受事易迁家。","诗赠金条脱，人逢萼绿华。"]},{"t":"玄洲倡和十首 其三 霞架海","f":"五言绝句","c":["日芒界金色，虹梁饮凤阿。","直把天孙袂，乌鹊讵填河。"]},{"t":"玄洲倡和十首 其四 鹤台","f":"五言绝句","c":["静夜飒灵风，神君语帐中。","至今双白鹄，时下五云峰。"]},{"t":"玄洲倡和十首 其五 桐华源","f":"五言绝句","c":["华林清散景，丹水碧凝脂。","落叶秋无数，玄都懒寄诗。"]},{"t":"玄洲倡和十首 其六 玄洲精舍","f":"五言绝句","c":["李基遗故鼎，赵啸绝风云。","悠悠千载下，更复属夫君。"]},{"t":"玄洲倡和十首 其七 紫轩","f":"五言绝句","c":["玄窗太霞气，赤书洞古文。","借问轩中主，莫是紫阳君。"]},{"t":"玄洲倡和十首 其八 火浣坛","f":"五言绝句","c":["真火本无候，真人自出现。","问埽劫灰馀，几见红莲变。"]},{"t":"玄洲倡和十首 其九 隐居松","f":"五言绝句","c":["露坛栖妙荫，仙籁降灵芬。","何时三易帔，重拂两梢云。"]},{"t":"玄洲倡和十首 其十 玉像龛","f":"五言绝句","c":["瑞仪温比玉，宝帔曲流光。","稽首大司命，料理住金乡。"]},{"t":"烟梅睡雀墨戏","f":"曲","c":["珍偶偏怜琼树，寒香漠漠纷纷。","谁见罗浮月黑，一枝同梦梨云。"]},{"t":"妆镜","f":"曲","c":["璧月朝朝琼树，明星处处阿房。","不似千秋镜里，与人能鉴兴亡。"]},{"t":"子昂风篁图为叶景修作","f":"曲","c":["不同主人看竹，稍似隐居听松。","一代亲承墨妙，叶公信有真龙。"]},{"t":"龙虎山郑良楚来从宗师入京","f":"七言绝句","c":["目送三峰鸾鹄群，更凭谷口唤夫君。","莫嫌病卧墙东叟，留得长镵管白云。"]},{"t":"松下渊明为郑明德作","f":"七言绝句","c":["归来不为督邮轻，自为松根长茯苓。","博浪金椎拈不起，倚锄却读相牛经。"]},{"t":"次韵答萨天锡见寄","f":"七言绝句","c":["推敲指点据吟鞍，苦为搜诗梦不閒。","谁会凤凰台上意，手挼黄菊看钟山。"]},{"t":"寄题陈生华山图二首 其一","f":"七言绝句","c":["西祀曾寻箭筈天，云台石室故依然。","雪驴嗅地鞭不起，一笑太平三百年。"]},{"t":"寄题陈生华山图二首 其二","f":"七言绝句","c":["华岳秋高不受寒，虎头粉墨意萧閒。","赤城别有思仙梦，长在明星玉女间。"]},{"t":"海粟松雪酸斋杂书一卷戏题于左","f":"七言绝句","c":["长沙老笔混狂澜，刮耳鸥波点素纨。","翰墨风流作三笑，最怜白纻一生酸。"]},{"t":"湖上莫归答吴养浩修撰","f":"七言绝句","c":["楼外鸦啼莫雨微，归鞭忙趁落花飞。","若教秃鬓翁能饮，肯羡山人倒载归。"]},{"t":"凌波仙","f":"七言绝句","c":["春云如水碧粼粼，谁见凌波袜上尘。","洛浦湘皋都是梦，手中花是卷中人。"]},{"t":"吴兴墨兰","f":"七言绝句","c":["墨君石友是同参，几叶光风染碧岚。","怅望王孙杳何许，年年芳草满江南。"]},{"t":"李遵道溪山春晓图","f":"七言绝句","c":["谁写江南雨后岑，清寒空阔扑云林。","何当载我图书去，共试野航春水深。"]},{"t":"烂柯图","f":"七言绝句","c":["一局棋残烂斧柯，山中日月竟如何。","归来记得神仙着，不比人间局面多。"]},{"t":"咏梨花","f":"七言绝句","c":["折得瑶花第一枝，清明时节寄他谁。","绝怜天上无真色，虢国夫人淡埽眉。"]},{"t":"偶成","f":"七言绝句","c":["黄篾楼中枕书卧，双鹤交鸣惊梦破。","青天堕下白云来，卷帘一阵杨花过。"]},{"t":"御史入山","f":"七言绝句","c":["喜闻宰相入山来，急唤山童埽碧苔。","云锁洞天三十六，楼台一一为君开。"]},{"t":"读临川集","f":"七言绝句","c":["班马文章老琢磨，咎夔心迹半彫讹。","执鞭愿作钟山吏，一袱字书随白骡。"]},{"t":"春水","f":"七言绝句","c":["雪消岩溜注湾陂，便有微澜作渺瀰。","时见幽人来照影，萧梁台畔立多时。"]},{"t":"春酒","f":"七言绝句","c":["雪度青天落酒杯，花枝半拂角巾摧。","陶公醉石苍苔满，不见猖狂李白来。"]},{"t":"春烧","f":"七言绝句","c":["日落山前野烧生，白茅黄苇地初晴。","明朝却赋雉带箭，呼酒冈头看火城。"]},{"t":"寄冯海粟待制附天目僧过广陵 其一","f":"七言绝句","c":["天目峰头一鹤回，白云持赠当寒梅。","琼花观里开包处，寄得玄砂白纸来。"]},{"t":"寄冯海粟待制附天目僧过广陵 其二","f":"七言绝句","c":["三都一序争传赋，借重西州皇士安。","惭愧山图经品藻，苦心留得后人看。"]},{"t":"寄冯海粟待制附天目僧过广陵 其三","f":"七言绝句","c":["昨日淮南召八公，扬州拟看醉围红。","赚人鸡犬云中去，策转江头控鹤童。"]},{"t":"玄洲独坐偶成","f":"七言绝句","c":["檐外菁葱玉树排，小山丛桂近当阶。","出云好看飙轮顶，云出飙轮忽被埋。"]},{"t":"墨海棠","f":"曲","c":["汉宫愁绝冷??，一蘸刘郎两鬓丝。","甲帐夜寒银烛冷，六铢云帔独来时。"]},{"t":"东坡书蔡君谟梦中绝句二放营妓绝句三虞伯生题四绝于后真迹藏义兴王子明家要予次韵凡九首 其一","f":"七言绝句","c":["日将公事湖中了，醉入重城列炬明。","自古大藩财赋地，古人偏得赋閒情。"]},{"t":"东坡书蔡君谟梦中绝句二放营妓绝句三虞伯生题四绝于后真迹藏义兴王子明家要予次韵凡九首 其二","f":"七言绝句","c":["谢女娇吟雪比盐，北台马耳见双尖。","衲衣政索歌姬笑，不道春寒绣被添。"]},{"t":"东坡书蔡君谟梦中绝句二放营妓绝句三虞伯生题四绝于后真迹藏义兴王子明家要予次韵凡九首 其三","f":"七言绝句","c":["写韵轩中尘不惊，与谁同蹑凤凰翎。","綵鸾可惜情缘重，只合清斋写道经。"]},{"t":"东坡书蔡君谟梦中绝句二放营妓绝句三虞伯生题四绝于后真迹藏义兴王子明家要予次韵凡九首 其四","f":"七言绝句","c":["钗头新绿荔枝红，那与江桃色味同。","闻道端明新进谱，一时殿阁起薰风。"]},{"t":"东坡书蔡君谟梦中绝句二放营妓绝句三虞伯生题四绝于后真迹藏义兴王子明家要予次韵凡九首 其五","f":"七言绝句","c":["香辟春寒玉辟尘，流苏斗帐醉和春。","一双明月都无价，寂寞人间第二人。"]},{"t":"东坡书蔡君谟梦中绝句二放营妓绝句三虞伯生题四绝于后真迹藏义兴王子明家要予次韵凡九首 其六","f":"七言绝句","c":["江南在处烟波好，浪迹先生不上船。","近就阖闾城下宿，可怜霜月夜娟娟。"]},{"t":"东坡书蔡君谟梦中绝句二放营妓绝句三虞伯生题四绝于后真迹藏义兴王子明家要予次韵凡九首 其七","f":"七言绝句","c":["青城樵者一衰翁，写罢乌丝满袖风。","消得玉堂金研匣，至今传入画图中。"]},{"t":"东坡书蔡君谟梦中绝句二放营妓绝句三虞伯生题四绝于后真迹藏义兴王子明家要予次韵凡九首 其八","f":"七言绝句","c":["听碾龙团怯醉魂，分茶故事与谁论。","纤纤玉腕亲曾见，秪有春衫旧酒痕。"]},{"t":"东坡书蔡君谟梦中绝句二放营妓绝句三虞伯生题四绝于后真迹藏义兴王子明家要予次韵凡九首 其九","f":"七言绝句","c":["白公种竹苏公柳，谈笑功名后世誇。","依旧葑云三万丈，断桥谁与筑堤沙。"]},{"t":"山中","f":"七言绝句","c":["一枝石瘦如麟角，六出花开似麝脐。","随意莓苔一杯酒，也胜骑马听朝鸡。"]},{"t":"顾定之竹石","f":"七言绝句","c":["龙孙乍脱绷儿锦，石面都皴弹子窝。","画妙通神欲飞去，虎头痴绝奈渠何。"]},{"t":"李仲宾雪竹","f":"七言绝句","c":["断缣黯淡何人墨，四十年前老蓟邱。","向使戴家多种竹，雪中那肯便回舟。"]},{"t":"李鍊师云閒卷","f":"七言绝句","c":["朝随飞鹤出檐端，倦鸟纷纷莫与还。","若似山居无用者，此身政不羡云閒。"]},{"t":"温日观蒲萄","f":"七言绝句","c":["日观一饮西凉酒，解写蒲萄绝代无。","请师截断葛藤路，还我黑月摩尼珠。"]},{"t":"桂枝词","f":"七言绝句","c":["桂树丛生枝婀娜，糁粟黄云欲成朵。","薰醒秋衣懒下床，金蟾啮断烧香锁。"]},{"t":"书道童总管赠蔡霞外诗后","f":"七言绝句","c":["多病潜夫懒入城，旋营草阁看阴晴。","竹宫桂馆花繁处，乞与霞仙烂熳行。"]},{"t":"新居快雨戏笔","f":"七言绝句","c":["旋埽林扉一榻横，绿阴幽底水纹平。","閒眠爱杀荷沟雨，玉磬池边无此声。"]},{"t":"子昂墨写萱草","f":"七言绝句","c":["碧浪湖头翰墨香，山蜂游趁午阴凉。","戏拈小笔涂幽草，正自无忧得可忘。"]},{"t":"林泉高士图","f":"七言绝句","c":["我本玄真老孙子，意托纶钓相娱嬉。","浮玉山前一瓢酒，颇恨时无颜太师。"]},{"t":"浔阳琵琶图","f":"七言绝句","c":["一幅面屏秋月圆，荻花枫叶染江天。","江州自是无司马，多少琵琶上别船。"]},{"t":"马远小景二首 其一","f":"七言绝句","c":["柳未藏鸦雪未消，春衫游子马蹄骄。","去年沽酒楼前路，错认桃花第一桥。"]},{"t":"马远小景二首 其二","f":"七言绝句","c":["玉砂卷海白模糊，千树梅花埽地无。","彷佛水仙祠下路，金枝翠带不胜扶。"]},{"t":"葛岭新居","f":"七言绝句","c":["葛洪川上有馀地，善和里中无故书。","为惜人间秋水观，鸡鸣犬吠又移居。"]},{"t":"台掾萨天锡求识予面而之燕南八月十四夜风雨宿菌阁绝句七首明日追寄之 其一","f":"七言绝句","c":["李公求识少陵面，未闻草堂三日留。","看君用意古人上，却愧无言与献酬。"]},{"t":"台掾萨天锡求识予面而之燕南八月十四夜风雨宿菌阁绝句七首明日追寄之 其二","f":"七言绝句","c":["鹤台道民掩柴扃，雁门才子宿寒厅。","恰有金华一樽酒，且置茅家双玉瓶。"]},{"t":"台掾萨天锡求识予面而之燕南八月十四夜风雨宿菌阁绝句七首明日追寄之 其三","f":"七言绝句","c":["巡官畏虎盛前呵，惊动燕山萨照磨。","剪烛对床诗未稳，从渠醉尉问谁何。"]},{"t":"台掾萨天锡求识予面而之燕南八月十四夜风雨宿菌阁绝句七首明日追寄之 其四","f":"七言绝句","c":["物华年鬓两骎骎，忆别何堪动此心。","乔木万株天一握，菌巢独自看秋阴。"]},{"t":"台掾萨天锡求识予面而之燕南八月十四夜风雨宿菌阁绝句七首明日追寄之 其五","f":"七言绝句","c":["高情常爱白云多，云为漫山雨注河。","野人宁知御史雨，秪见石田苏晚禾。"]},{"t":"台掾萨天锡求识予面而之燕南八月十四夜风雨宿菌阁绝句七首明日追寄之 其六","f":"七言绝句","c":["走送蒲衣庵外路，归时望见赤山湖。","林子求看换鹅帖，胡郎传送捕鱼图。"]},{"t":"台掾萨天锡求识予面而之燕南八月十四夜风雨宿菌阁绝句七首明日追寄之 其七","f":"七言绝句","c":["内台最近燕南幕，博士台郎有此除。","山泽何当大人赋，寄声多谢马相如。"]},{"t":"缉熙殿御制墨梅诗帖","f":"七言绝句","c":["宣和妙赏缁衣句，传在夷门作胜谈。","行殿春风四十载，玉妃终老向江南。"]},{"t":"王子明求题高侍郎雨竹","f":"七言绝句","c":["雨立修篁似戟枝，墨君留影故僛僛。","房山秪忆巴山夜，及见官奴把烛时。"]},{"t":"楼居春晓望玄圃","f":"七言绝句","c":["子晋新宫倚太霞，绕湖烟火万人家。","观台一面无人处，日出烟消都是花。"]},{"t":"四贤帖","f":"七言绝句","c":["四明狂客已乘云，海内文章有二君。","可惜戴华刘伯寿，只今零落凤凰群。"]},{"t":"月夕爱南窗竹影","f":"七言绝句","c":["两丛小竹南窗下，露叶风枝共秋夕。","月明见影忽自笑，移得王淮凤翔壁。"]},{"t":"李士行枯木","f":"七言绝句","c":["两株苍柏如蓬首，皮毛剥落心不朽。","曾见春风春雨来，相看唤作忘年友。"]},{"t":"仙山楼观图为马仲礼作","f":"七言绝句","c":["忆共能书蔡少霞，良常洞口看桃花。","人间诗酒耽迷了，三百年来不到家。"]},{"t":"张公甫铁山隐居图","f":"七言绝句","c":["铁山曾照铁衣寒，南渡功名有足观。","不见元丰全盛日，钱镠孙子已黄冠。"]},{"t":"隐居图","f":"七言绝句","c":["壶浆相饷过溪东，缟袂青裙笑语中。","何必桃源寻旧路，太平閒作祝鸡翁。"]},{"t":"赵魏公写生梨花折枝","f":"七言绝句","c":["玉面浑无獭髓痕，春风洗绿上飞裙。","遥知姑射山头雪，化作杨君梦里云。"]},{"t":"张仲敏钩勒风林","f":"七言绝句","c":["墨君神骏出洋州，形似无如老蓟邱。","可惜风林半窗月，试凭老眼为双钩。"]},{"t":"鹤山书院","f":"七言绝句","c":["寂寂茅堂掩昼门，藤阴花气小池浑。","也知建邺青精饭，不到临邛白发孙。"]},{"t":"觉林院","f":"七言绝句","c":["石湖园中数株石，堆向觉林僧子家。","眼前醒醉若无语，领客绕庭唯看花。"]},{"t":"归自雨中写况寄景修博士","f":"七言绝句","c":["蛙处水连围屋草，鸠时雨烂覆檐花。","移过书窗金鹊尾，秪言浑似野人家。"]},{"t":"葛岭柬乐閒高士并寄公文道弟","f":"七言绝句","c":["葛洪井上访贞居，一饮甘泉足自如。","拂袖莫嫌狂散甚，子非知我我知鱼。"]},{"t":"次韵实喇卜郎中题襄阳官舍","f":"七言绝句","c":["岘山日落春风起，竹坞湘桃零乱开。","倒著接䍦驮瘦马，无人知道使君来。"]},{"t":"葛岭杂书","f":"七言绝句","c":["小娃小艇无踪迹，只有荷花雨溅裙。","净洗一方天水碧，不教歌板污游云。"]},{"t":"仲敬画华阳草堂图","f":"七言绝句","c":["珠树风来学凤鸣，玉泉雨过作琴声。","识得良常洞中路，前生我本山玄卿。"]},{"t":"遵道竹枝","f":"七言绝句","c":["筼筜谷口白云生，云里琅玕万玉声。","惊破幽人春枕梦，一窗斜月半梢横。"]},{"t":"避暑图","f":"七言绝句","c":["雪藕冰盘斫鲙厨，波光帘影带风蒲。","苍生病渴无人问，赤日黄埃尽畏途。"]},{"t":"径山寺僧山水","f":"七言绝句","c":["澄心茧纸墨花香，上有元晖古印章。","怪底径山山寺里，老僧衣袖著潇湘。"]},{"t":"白无咎黄蜀葵","f":"七言绝句","c":["金铜仙人雨中立，铅泪恰如辞汉时。","倾心脉脉何所待，愿见白日光陆离。"]},{"t":"修竹士女图","f":"七言绝句","c":["空谷佳人玉佩珰，琅玕斜搭领襟长。","杜陵野老多才思，解道风吹细细香。"]},{"t":"墨杏花折枝","f":"七言绝句","c":["折得邻墙红杏枝，春风偷染墨胭脂。","恰如误入仙山路，虎啸林深月暗时。"]},{"t":"晋彦博士以诗索和甚愧率然观者勿笑其窘步","f":"五言律诗","c":["凿涧盛春雨，新流绕舍前。","何当留太白，相与学思玄。","碧洞无人扫，丹梯有路缘。","催诗苦云迫，莫笑竦鸢肩。"]},{"t":"辅成观张上卿墓庐","f":"五言律诗","c":["青牛谢车御，白鹤叹人民。","阁有凌烟像，桥无进履身。","平生玉櫑具，此地石麒麟。","荡荡传宗业，中朝倚外臣。"]},{"t":"风雪中得金陵诸公书二首 其一","f":"五言律诗","c":["雪作众禽惊，窗幽乱霰鸣。","愕然身濩落，暮矣岁峥嵘。","松竹聊娱拙，乾坤苦忌名。","故人不相贷，书札到柴荆。"]},{"t":"风雪中得金陵诸公书二首 其二","f":"五言律诗","c":["落木从风靡，支流趁谷斜。","山空不须说，岁去若为遮。","饥鹤挦窗纸，寒鱼嚼雪花。","推书更清坐，席暖到昏鸦。"]},{"t":"天谷庵","f":"五言律诗","c":["十三科取士，救世岂无方。","倏送孤鸿举，难追八骏骧。","金坛犹著号，碧落旧为郎。","剑化丹垆在，山寒井水香。"]},{"t":"碧玉庵","f":"五言律诗","c":["廿四岩前客，能忘贺监居。","乖龙嗔草檄，古象泣遗书。","把袂风尘表，近公冰雪如。","时来青琐闼，晚节要蘧庐。"]},{"t":"湖寺拥碧轩","f":"曲","c":["喧寂一尘隔，湖滨出宝坊。","荷阴分补衲，水气杂烧香。","书勘乌皮几，茵敷白?床。","从来已公屋，诗客许徜徉。"]},{"t":"万致柔还省亲舍仆闻而往候道中得此","f":"五言律诗","c":["数里平冈路，仙山迹渐分。","柴荆来鹊语，村落去人群。","粉阵松崩雪，涛头日濯云。","不缘停仆御，直以候夫君。"]},{"t":"寄洞庭王子正","f":"五言律诗","c":["洞庭山似簇，银阙翠芙蓉。","安得沧浪子，同寻缥缈峰。","鱼龙随水落，橘柚待霜浓。","未必桃源似，云帆蹑去踪。"]},{"t":"奉和揭学士听松轩","f":"五言律诗","c":["何年种松子，此地听松声。","涛响风还作，山空夜自明。","一瓢嫌物累，九奏感时清。","得似苍髯叟，长依白玉生。"]},{"t":"孤山晚步寄和靖掌祠怀中庸子","f":"五言律诗","c":["玛瑙坡前立，荒陂接葑田。","试从樵子径，往觅仆夫泉。","众草寒犹短，群峰晚更妍。","谁欤结真隐，共老太平年。"]},{"t":"十二月三日雪","f":"五言律诗","c":["快雪真无价，丰年定有期。","腊前才一白，至后已多时。","玉展琳琅步，花团蛱蝶枝。","春风在天上，飘入万年池。"]},{"t":"煮石窝","f":"五言律诗","c":["仙人白石子，服食受奇方。","王烈犹餐髓，初平枉叱羊。","砂床收箭镞，玉屑备糇粮。","借尔弥明鼎，行窝到处将。"]},{"t":"良常草堂图","f":"五言律诗","c":["邻近方隅洞，良常别有天。","草堂朝看雨，药圃夜舂泉。","邈矣卢鸿乙，奇哉鲁仲连。","君看遗世者，若个是神仙。"]},{"t":"斋居偶兴","f":"五言律诗","c":["绝涧多灵石，中开小洞房。","醉醒依竹素，晴雨看梅黄。","树暗莺声涩，岩虚水韵长。","未能超贾马，自足上羲皇。"]},{"t":"午日柬杨廉夫","f":"五言律诗","c":["客有拥琴至，吾宁折简招。","足音垂谷口，雨气截山腰。","酒倩红泉泻，花为绛节朝。","不嫌泥泞极，一舸段家桥。"]},{"t":"雨中","f":"五言律诗","c":["推枕蘧然觉，高斋人迹稀。","卷帘芳草短，看雨杏花肥。","薄暮寒仍在，中林愿稍违。","一迁随谷鸟，乔木是耶非。"]},{"t":"除夜","f":"五言律诗","c":["忽忽岁云暮，徒兴白首嗟。","山留待伴雪，春禁隔年花。","把卷因遮眼，分饧且胶牙。","自缘身懒惰，莫遣送穷车。"]},{"t":"涧北梅□三月始华","f":"五言律诗","c":["阴涧残梅蘖，临流一向欹。","但存孤注在，敢恨一生迟。","冻雨如相喣，春寒不受吹。","后时翻见独，宰物遂成私。"]},{"t":"萼绿梅","f":"五言律诗","c":["山中古仙子，无言春寂寥。","玉容澹朝雨，翠气湿微霄。","临风怯玩影，弄雪妒攀条。","拟觅何郎句，还凭翠袖招。"]},{"t":"山水便面为柳道传作","f":"五言律诗","c":["箧笥秋非远，尘埃暑实烦。","遂游千里目，稍待一凉恩。","僧阁依旁岭，渔梁跨别村。","谁能从象外，试觅武陵源。"]},{"t":"马伯庸御史石田山房","f":"五言律诗","c":["监州遗爱地，御史读书堂。","弦诵犹怀鲁，田园独在光。","白茅编野屋，翠竹被溪梁。","欲赋淮南隐，知君意不忘。"]},{"t":"寄樊子中打碑者","f":"五言律诗","c":["樊迟讵学圃，可论金石交。","常赋旧文字，如见古陶匏。","汉篆龙回壁，梁书室卧蛟。","墨卿吾与尔，聊复隐三茅。"]},{"t":"呈揭曼硕学士","f":"五言律诗","c":["柴荆马粪间，蛛网动相关。","阁老因移疾，鲰生赖订顽。","雨凉新竹健，沙僻睡凫閒。","如许清秋意，扁舟犹忍还。"]},{"t":"曲密亭","f":"五言律诗","c":["水盩山复屋，亭此可婆娑。","蜗角地虽少，蜂房春自多。","橘藏商皓乐，凤忆楚狂歌。","何必天津上，远寻安乐窝。"]},{"t":"流杯涧","f":"五言律诗","c":["古木蟠幽涧，层峦叠翠台。","水归苍玉峡，风引绿荷杯。","我自知鱼乐，人谁祓禊来。","惜无鼠须笔，写记刻岩隈。"]},{"t":"菌阁","f":"五言律诗","c":["岩架菌芝阁，榜题松雪扉。","云来画檐宿，龙向墨池归。","对几琴三叠，倚阑山四围。","仙灵能夜降，应得㖟玄机。"]},{"t":"积雨","f":"五言律诗","c":["饱听三峰雨，閒题七月诗。","水深荷意怯，田冷稻心迟。","蛙黾阴争盛，蛟龙势亦随。","苍茫不可问，身外付云移。"]},{"t":"早秋","f":"五言律诗","c":["每嫌新酒少，尚喜故交稠。","篱落三家墅，梧桐十日秋。","月生微顾兔，星淡没牵牛。","亦欲观多稼，江湖雨未周。"]},{"t":"次韵元镇玄文馆有怀","f":"五言律诗","c":["林气早知雨，黤淡研苔滋。","素飙惊閒幔，朱实委清池。","将整还山旆，复乱故园思。","拿舟倘未远，弭棹一来兹。"]},{"t":"开元真人见贻刘商观弈图石刻毫发布缕皆尽精妙盖李龙眠临唐画本茅君彦模勒为玉局仙翁所藏云","f":"五言律诗","c":["薪桂苏兰者，能来立坐隅。","徒闻玉楮刻，遂信石枰图。","妙迹传仙李，高名重大苏。","向来林下意，不敢易樵夫。"]},{"t":"乙亥元日试笔","f":"五言律诗","c":["自古三朝节，于今一笑看。","问年书亥字，献岁出辛盘。","黔突多蒸术，红冰剩浴丹。","行行追胜事，步步埽春寒。"]},{"t":"无锡华子英溪山胜槩亭","f":"五言律诗","c":["共爱溪山住，输君胜槩多。","疑将草堂画，展向镜湖波。","鹳雀深松柏，凫鹥足芰荷。","更修仁知术，乡社乐婆娑。"]},{"t":"蛛网落花","f":"五言律诗","c":["飞花堕锦茵，蛛网解留春。","露垂沾更重，风破舞还频。","不逐燕嘴泥，宁随马足尘。","游丝复染惹，流浪何足嗔。"]},{"t":"题墨兰赠别于一山之京师","f":"五言律诗","c":["三月愁送客，春寒雨如霰。","冥冥返塞鸿，悄悄栖梁燕。","扬帆五十日，蓬莱望中见。","欲持猗兰操，一奏南薰殿。"]},{"t":"雪斋","f":"五言古诗","c":["骑驴吟雪诗，煮茶煎雪水。","何如埽一室，置身虚白里。","君家有故事，高卧殊未已。"]},{"t":"龙洞","f":"五言古诗","c":["山中春水泛，蜕骨长于树。","拿舟探穴口，甚深不敢渡。","穷冬桃始华，烂然珠光处。"]},{"t":"张师夔画谢家池塘","f":"五言古诗","c":["春风飒然至，幽人午梦醒。","遥见池塘绿，不知春草生。","如何骑马客，亦向梦中行。"]},{"t":"春山晴霭图","f":"五言律诗","c":["危亭面悬瀑，深坞著茅堂。","群木相掩薄，风披如有香。","避世真乐土，欲往川无梁。","隐沦倘见招，岁莫从徜徉。"]},{"t":"兰雪斋为金坛王敬赋","f":"五言律诗","c":["谪仙有妙语，清风洒兰雪。","高怀千载下，子独慕芳洁。","春冰断瑞花，晨露滋奕叶。","端居味道腴，光景庶不灭。"]},{"t":"再赋天池","f":"五言律诗","c":["巃嵷古墩邱，泓潭浸其股。","金碧争荡磨，穿穴稍旁午。","斩松罗石榻，玄芝错神浒。","遥应玉女盆，润及黄精圃。"]},{"t":"滨洲云巢图","f":"五言古诗","c":["苍山不受寒，裹以白兜罗。","借云以为暖，我意不在多。","小营丹鹤巢，高栖翠云柯。","飞仙度鸾笙，老人卧鸡窠。","谁能江海去，风雨一渔蓑。"]},{"t":"寄题刘彦基丹室","f":"五言古诗","c":["昔闻冲虚宫，远在锦江头。","往来多异人，东望不可求。","借问鸿宝书，枕中今在不。","尚馀一丸药，光景夜不收。","食之生羽翼，飞去十二楼。","下视何苍苍，至情难久留。","我将拾瑶草，迟子于玄洲。"]},{"t":"十月十八夜震泽风大作明日大雪异常又明日甲子日出大寒","f":"五言古诗","c":["弱龄逃世网，一勇以求志。","折旋四十载，竟日坐有累。","大拙使为巧，小朴使为器。","用是役于人，夫岂足言智。","飘风鼓具区，如我长噫气。","追惟年运往，通夕遂忘寐。","圣人罕言命，天道殊难致。","委顺待未来，馀日敢终弃。"]},{"t":"次韵晋卿翰林赠陈秉彝","f":"五言古诗","c":["金华黄太史，出为儒台冠。","诗文齐六经，奇古谁敢传。","如掇明月珠，妙在九曲穿。","而子工笔札，狗监非所荐。","挈之登龙门，果获尾时彦。","孜孜勤执经，矻矻劳染翰。","敏手不暇给，精华且屡换。","怜才吾辈事，子乃羞自献。","由兹数来往，无事辄相见。","湖岭错萦纡，烟霞争变幻。","一夕快雨馀，春物已消半。","言归天台奥，俄顷语离散。","此手不易执，明日柁楼饭。","迢迢望白云，瀑布声许悍。","赤城跨沧海，朝霞以为岸。","倘遇仙者徒，勿易樵牧贱。","予衰志求道，千载犹暮旦。","老经三百家，一一理残卷。","霜毫犯冠箨，墨汁滓衣汗。","何功使愿果，尽力输老腕。","子书能瘦硬，泪眼秋隼健。","唯馀箧中字，照我目光烂。","送子望崖返，回目穷海甸。","春夕岂不短，反侧移漏箭。","才梦金庭游，还逐涛江乱。","荐知家庭乐，旭日阴始泮。","身扶老人杖，衣忆慈母线。","还期当及时，迟子秋水观。","栖栖寡俦侣，孤坐至日晏。","追步太史作，用以申缱绻。"]},{"t":"书怀二十韵奉呈虞集贤","f":"五言古诗","c":["昭代千龄运，斯文一柱功。","初当延祐日，晚识广陵公。","朝士因推毂，先生猥击蒙。","暌乖遗廿载，寤寐接孤风。","太史山川彦，仙儒馆阁崇。","置身清切上，用志杳冥中。","句法黄初过，才名冀北空。","朔南驰使节，江汉借归篷。","酒问馀杭姥，泉寻六一翁。","境非秋水观，寺即紫微宫。","侍坐要王远，移家近葛洪。","于焉承咳唾，足以振罢癃。","卓尔身为贵，胡然老见攻。","战肥终道胜，德重岂途穷。","玉趾閒迂步，麻衣病鞠躬。","茶烟窗冉惹，墨沼树玲珑。","饥甚无瑶草，招来有桂丛。","输心何落落，把袂辄匆匆。","易进乘轩鹤，难追戏海鸿。","明朝去吴会，长笑为谁雄。"]},{"t":"元日雪霁早朝大明宫和辛良史省郎廿二韵","f":"五言古诗","c":["才设中庭燎，俄看密霰飘。","岁开环甲纪，星动指寅杓。","凤集天门榜，珂鸣月殿桥。","卿云同四表，和气集三朝。","陛级肪初截，云层玉旋雕。","句陈分彩队，步辇簇青腰。","积屑承盘重，吹花到笏消。","逶迤光斧座，凌乱缀珠翘。","乐共垆烟合，班随翠袖招。","阆风游广汉，玉局道逍遥。","北戏鱼龙舞，中岩虎豹调。","旌旗攒赑屃，冠剑掠招摇。","穆酒曾觞母，洪崖及见尧。","万年临紫极，一白庆璇霄。","朝会仪如此，骞腾意颇饶。","身唯参寂寞，世岂绌纷嚣。","姑射消疵疠，蓬莱倚泬寥。","瑶华搀戴胜，珠树引回镳。","有术探鸿宝，何人识爨焦。","竟须穷海岱，直拟并松乔。","书就神床写，香从别室烧。","怜君守华省，琢句废春宵。"]},{"t":"茅山四十四代宗师牧斋真人升仙谣","f":"五言古诗","c":["昔爱西城记，华易许遍窥。","醉持龙节舞，寒借鹿裘披。","秪忆山中乐，宁期世外悲。","及传南岳剑，难驻赤城师。","毕道能无待，玄科本有期。","紫宫新坐席，金箓古威仪。","菌石哀泉咽，松花泣露垂。","他年归白鹄，尚慰里民思。"]},{"t":"墨龙","f":"曲","c":["高昌世子写墨龙，此龙乃出开元东井中。","东井水与天河通，龙下取水遗其踪。","道人识为黑帝子，逃入世子之笔锋。","井头夜半飞霹雳，元气淋漓雪色碧。","一锁银床五百年，才点目睛生羽翼。"]},{"t":"卢疏斋集","f":"七言律诗","c":["人物西清第一流，曾看绣斧下瀛洲。","难求冀北千金骨，空载江南数斛愁。","小谢梦无青草句，大苏诗有景疏楼。","敬亭依旧峨嵋月，付与骑鲸汗漫游。"]},{"t":"书东坡先生画像","f":"七言律诗","c":["峨嵋秀色杳难攀，玉局仙人不受閒。","南斗日躔韩吏部，西湖风气白香山。","宁教刺舌奸邪党，可惜低头侍从班。","试问东坡铁柱杖，于今海上未曾还。"]},{"t":"寄谢张子寿御史京口留饮","f":"七言律诗","c":["卖药南徐两日留，绣衣相对似清秋。","借抄衡岳元君传，挽住湘潭使者舟。","安道推琴元有在，桓伊弄笛若为酬。","归来独醉投山阁，梦寄新诗与率牛。"]},{"t":"宗师云江还山虞侍讲惠诗有词请大洞箓","f":"七言律诗","c":["丹凤楼前返羽车，清诗满袖出京华。","雕虫徒刻三年楮，补衮应餐五色霞。","太白晚传青绮帔，元种早授玉门砂。","要知不隔金闺步，常是相从太极家。"]},{"t":"次韵柯敬仲学士见寄","f":"七言律诗","c":["故人往往天禄阁，我尝梦见燃青藜。","重帘月落秋燕往，九衢尘动朝鸡啼。","能传米芾书画学，稍忆卢鸿林鹤栖。","繇来避世向金马，讽谏得君宁滑稽。"]},{"t":"经碧浪湖奉怀吴兴公","f":"七言律诗","c":["湖水秋空玉色匀，蒹葭纤雨上纶巾。","重来羊岘谁沾泪，却顾龙门不见人。","独放酒船寻鲙具，谁容狂客吐车茵。","西风白羽元非用，只为人间苦障尘。"]},{"t":"赠商学士德符","f":"七言律诗","c":["鞭凤笞鸾下紫烟，笔床尘尾意翛然。","一贫自信如陶侃，三绝谁能似郑虔。","金碧瀛洲扶御扆，玉华仙露洒经筵。","寿岩独立风尘表，却笑灵椿是小年。"]},{"t":"泰定丁卯沙溪元日按志","f":"七言律诗","c":["山世行藏本不羁，江东节序片帆随。","三朝犹是嘉平腊，一集又题丁卯诗。","赤石青林含古色，白沙翠竹照清漪。","春风浩荡鸥波兴，终要南山雾豹姿。"]},{"t":"寄李季和","f":"七言律诗","c":["孰与言诗李髯叟，一日不见已为疏。","因观故京来白下，载闻新作过黄初。","小峰待月许携被，中林放鹤要回车。","杜陵醉歌不易得，岂惜华阳真逸书。"]},{"t":"舟次滆湖用柳博士梦薛玄卿诗韵寄倪元镇兼怀道传明德","f":"七言律诗","c":["思远重逢茅小君，香消酒尽路三分。","五湖归思浮天水，一霎秋阴过雨云。","柳子篇章浑可法，花奴弦索共谁闻。","唯应自洗唐溪石，填得金泥小篆文。"]},{"t":"曲林真人遗以乳石杯盘赋诗以谢","f":"七言律诗","c":["上党搀天入醉魂，元功有意琢云根。","小于药玉荷心盏，大称霜皮木瘿樽。","藉草饮时留洞吏，隔花捧处倩山猿。","殷勤更借弥明鼎，寒夜联诗酒屡温。"]},{"t":"读元次山集感而有作","f":"七言律诗","c":["漫叟古之贤达欤，愤世直言七不如。","著书首补云门乐，取醉政赖石湖鱼。","湘中韶濩遗欸乃，天下漫浪知猗吁。","饿死杜陵拾遗老，唯有舂陵能起予。"]},{"t":"次韵刘伯温御史春游","f":"七言律诗","c":["草木幽馨涧道微，白云拄杖去如飞。","独寻玉女洗头处，相伴仙人采药归。","几叠翠微深杳杳，一帘红素乱霏霏。","何堪酒债兼诗债，老却江南白苧衣。"]},{"t":"寄吴兴赵承旨","f":"七言律诗","c":["亭下鸥波好放船，苍苍葭菼水如天。","投纶渔父小垂手，化蝶秋虫大学仙。","麻纸丹书应满笈，鳊鱼紫蟹不论钱。","清真逸少谁同传，独许华阳许叔玄。"]},{"t":"方广寺石桥","f":"七言律诗","c":["绿玉飞梁碧藓封，羽人来倚瀑帘风。","偶翻贝叶经台上，与散昙华茗椀中。","有象到头终幻灭，无生弹指即虚空。","春寒大展三衣坐，百衲云山一线通。"]},{"t":"魏国赵夫人管君挽诗","f":"七言律诗","c":["曾谒西池閟殿春，赐加大国宠疏频。","择婿当年郗太傅，能书今日卫夫人。","玉镜离台空掩月，宝衣堆桁暗凝尘。","千秋乡中名不没，墓有通儿书老银。"]},{"t":"寄京师吴养浩修撰薛玄卿法师兼怀张仲举右谒因寄 其一","f":"七言律诗","c":["百壶美酒那消忧，数卷道书天与游。","既雨秋城苦泥淖，未寒病骨思衣裘。","看我目光牛背上，忆君佩声凤池头。","情知契阔宁复语，白鹄斯举不可留。"]},{"t":"寄京师吴养浩修撰薛玄卿法师兼怀张仲举右谒因寄 其二","f":"七言律诗","c":["风起春城散客忧，玉京台殿忆同游。","云开万象森丹阙，金织双龙盘翠裘。","此日听鸡趋禁籞，何年骑鹤过山头。","从君试觅王乔术，学化仙凫任去留。"]},{"t":"寄京师吴养浩修撰薛玄卿法师兼怀张仲举右谒因寄 其三","f":"七言律诗","c":["十年京国总忘忧，诗酒风流共贵游。","溪月夜游鳷鹊观，滦云晓湿鹔鹴裘。","书来慰我临池上，秋去思君到水头。","更忆何人张仲举，于今江海为谁留。"]},{"t":"题范德机编修东坊藁后","f":"七言律诗","c":["一编上有东坊字，惭愧诗中见大巫。","直想瘦生如饭颗，竟从痒处得麻姑。","咸池水浅孤黄鹄，空谷天寒病白驹。","拟共风流接尊酒，秪愁尘土没双凫。"]},{"t":"御史中丞马公伯庸有赠萨天锡还金陵长句因次韵寄上","f":"七言律诗","c":["射策甲科今廿载，尺书难信石城潮。","径登乌府持天宪，犹倚青溪望使轺。","四月莺啼夹城仗，千官花拥大明朝。","会因桂树思真隐，独是淮南作赋招。"]},{"t":"次韵杨廉夫送僧仲猷归澄江礼敬寺","f":"曲","c":["千岁岩头坐两夏，秋来忽梦刀头环。","笑别白?辞鹫岭，飞乘赤鲤下仙山。","桂子纷纷向人落，杨柳依依迟子还。","子云奇字不易得，只许澄江窥一斑。"]},{"t":"危太朴入都为题云林画幅","f":"七言律诗","c":["故人渺在云林端，手种梓漆阴团团。","不愤读书从鬼谷，何嫌卖药近长安。","白日定趋天禄阁，青春宜著鵔鸃冠。","相思洒尽金壶墨，三十六峰生莫寒。"]},{"t":"怀薛玄卿","f":"七言律诗","c":["丹楼百尺倚云霄，有客怀仙兴独高。","腰下苍精缠宝气，眉间脉理卷金毛。","拟招薛子青田鹤，与钓任公碧海鳌。","幸自苍顽同木石，思君一夕梦劳劳。"]},{"t":"二月病怀","f":"七言律诗","c":["煮药香中听雨眠，都缘未熟养生篇。","雪消春水深三尺，日上花阴过几砖。","世事悠悠高枕外，衡门寂寂暮霞边。","自惭病鹤摧颓甚，却顾云霄意悄然。"]},{"t":"上清外史薛玄卿寄题菌阁且约以游武夷次韵以答","f":"七言律诗","c":["馀杭山水著飞楼，楼外长林地转幽。","十亩树阴閒濯足，一帘荷气晓梳头。","山涛举代嵇康懒，张说论文薛稷忧。","萧散人间两外史，平生犹欠幔亭游。"]},{"t":"玄览真人示以李遵道旧诗一章俾次韵悼之将寄其子克孝","f":"七言律诗","c":["仙李如何竟小年，满堂图障惨风烟。","青山扪虱谁同话，赤脚骑鲸自上天。","名世岂唯书画学，起家犹望孝廉船。","无因得寄松花酒，一洒清明笔冢前。"]},{"t":"赠渔樵侣","f":"七言律诗","c":["郁木坑前负薪者，道士矶头垂钓翁。","我辈与结平生友，夫君还有古人风。","水羞凉味蒲芽白，野饭昼香松菌红。","见说行藏多岁月，不离三泖九山中。"]},{"t":"次韵杨廉夫见投","f":"七言律诗","c":["白发黄冠归故里，某邱某水昔曾经。","石泉新处钻槐火，山雨多时拾菌钉。","溪叟扶犁天际去，邻娃吹笛夜深听。","杜陵醉眼元空阔，解道乾坤水上萍。"]},{"t":"吾爱吾庐","f":"七言律诗","c":["吾爱吾庐聊复尔，眼前白石与苍苔。","水从林木阴中过，风自房栊曲处来。","薄有馀情归竹素，竟无长物受尘埃。","先生闭户成真懒，诗债敲门不厌催。"]},{"t":"江山胜槩楼为龙虎黄希石作","f":"七言律诗","c":["仙人元自好楼居，快展江山极目初。","天上孙登一弦曲，云中梁鹄八分书。","金明海岫晨暾发，玉奏风涛夜籁虚。","跪席焚香疑有待，麻姑行按小方诸。"]},{"t":"乙亥二月还钱塘书怀寄刘师鲁","f":"七言律诗","c":["黑头时与王孙别，春草又青天一涯。","贫甚冯驩犹有铗，归来丁令已无家。","葑田湖窄残舟少，墓道山荒剩屋斜。","还忆菌巢书数卷，雪麋应护手栽花。"]},{"t":"答杨廉夫二首 其一","f":"七言律诗","c":["弄水摘花春可怜，风雨倦寻茅步船。","我家南坞有灵石，龙井西头无杜鹃。","野雀乱雏畏人过，弱柳委地趁蚕眼。","子云胡为甘寂寞，后世何人知太玄。"]},{"t":"答杨廉夫二首 其二","f":"七言律诗","c":["黄篾楼中惟饮酒，楼下长沟凫雁多。","湾头桥断浮青草，湖面风来生白波。","馋奴竟煮脱绷笋，老鱼戏唼如钱荷。","诏书宽大到海角，河北饥氓争倒戈。"]},{"t":"李宁之煮茶亭","f":"七言律诗","c":["桐君山下一区宅，木茂土肥泉水香。","槎头钓鱼秋雨足，亭子煮茶春日长。","两山徒为盘谷隐，一水尚系平泉庄。","莫厌身名俱隐约，会见輶轩来晦冈。"]},{"t":"涧阿坐雨寄以敬","f":"七言律诗","c":["载雨过湖山雨重，放水出山湖水浑。","窗风乱解丛篁箨，渠溜直穿双树根。","白须道士烟霞癖，锦里先生芋栗园。","想见南邻邱架阁，也嫌泥泞不过门。"]},{"t":"十二月五日雪晴","f":"七言律诗","c":["日光玉洁千峰立，快雪晴时一气凝。","当昼垆亭摧扫巷，犯寒渔榜借收冰。","松皮石裂号饥鼠，窗隙尘消触冻蝇。","青茁菜芽浑可爱，倩谁春餤捲红绫。"]},{"t":"张参谋席上奉饯高昌别驾朝宗通守如京师并简兼善尚书","f":"七言律诗","c":["梁溪宅里閟烟霞，使者淹留日未斜。","天上夔龙图治道，舟中李郭望京华。","十三弦送黄柑酒，第二泉煎紫笋茶。","寄谢南宫达夫子，会同鸡犬忆仙家。"]},{"t":"读戴帅初集","f":"七言律诗","c":["剡源诗卷落吾手，便似移家太白峰。","学道昔惭山世远，知人今愧郭林宗。","空山乐书有遗谱，白日天马无留踪。","太息斯人不可见，厌将两耳闻寒蛩。"]},{"t":"赠刘伯温大监","f":"七言律诗","c":["台阁如公最有称，轺车骢马数能乘。","校书在昔专刘向，秘监于今复魏徵。","汗简削成金作匮，泰阶平处玉为绳。","信有仙人唯寂寞，侧身长倚白云层。"]},{"t":"送郑明德适越","f":"七言律诗","c":["四十日春廿日雨，问花寻柳意茫然。","竹根卧瓶高笔冢，灶下生薪连术烟。","茅家名馀铁垆步，龙井气胁金沙泉。","稽山酒船速回棹，迟子归来烹蕨拳。"]},{"t":"虞先生送张元朴回龙虎有云麈尾每怀张外史鹅群今属薛玄卿元朴索次韵","f":"七言律诗","c":["想见先生戴笠行，黄茅冈上看阴晴。","承闻祖道同疏傅，鄙说还乡似长卿。","海内好诗元自少，江西行李不嫌轻。","谪仙爱与元丹语，烟子而今亦有名。"]},{"t":"秋日晚兴","f":"七言律诗","c":["暝色入林烟火微，莫雨欲来如有期。","野雀喧争楝树子，幽人行把菊花枝。","山空始见水泉涸，寒至乃索衣裘迟。","莫惜题诗将寄远，不多故旧在京师。"]},{"t":"道馆雅集听琴次杨彦常韵","f":"七言律诗","c":["幽蒿细竹满墙间，雨后危墙似断山。","一室了忘尘世隘，诸君能赏病夫閒。","池巡野鹤鱼苗缘，土蚀秋虫菜甲斑。","我不鼓琴偏识趣，绝怜失势重跻攀。"]},{"t":"赠危太朴","f":"七言律诗","c":["莫怪道人居处僻，柴门今始为君开。","曾从小有探华盖，不向昆明数劫灰。","秋水渚涯浮地肺，茅君局任守天台。","倦游早欲依香火，付与卢敖戏九垓。"]},{"t":"南洞居三首 其一","f":"七言律诗","c":["绝涧垂萝一径分，碧岩不与众峰群。","秪疑洞口谽谺石，浑是山头片段云。","病试术方疏药捡，书移冰研近炉薰。","幽人许掾相问讯，转忆山阴王右军。"]},{"t":"南洞居三首 其二","f":"七言律诗","c":["山中栋宇自齐梁，唯数南岩古道场。","虎洞窥来光剡剡，鹅池临罢绿泱泱。","天寒最觉松神王，丹化悬知鹤寿长。","珍重平生金鹊尾，大茅峰下独焚香。"]},{"t":"南洞居三首 其三","f":"七言律诗","c":["华阳南洞幽人居，幽人本是山泽癯。","玉门砂无勾漏令，太平酒胜步兵厨。","洞穴嵚岩肺腑隔，菖蒲根节龙蛇枯。","愿从岁晚饱肥遁，不待著论称潜夫。"]},{"t":"送日本僧","f":"七言律诗","c":["上人住处扶桑国，我家亦在蓬莱邱。","洪涛拍屋作山立，白云绕床如水流。","住世不知谁是客，多时忘却故园秋。","明朝相别思无尽，万里海天飞白鸥。"]},{"t":"钱塘西即事","f":"七言律诗","c":["苔竹沟深迷远近，置我洞庭青草湖。","飘风骤雨且高卧，来牛去马非良图。","中散几时应罢锻，舍人何日共投壶。","为留兵厨醽醁酒，待看池莲冰雪肤。"]},{"t":"鳌峰宜晚亭","f":"七言律诗","c":["鳌峰亭子偏宜晚，约下烟光与细看。","独鹤归来频寄语，夕阳舂外一凭栏。","昔游谢眺空陈迹，回首敬亭生莫寒。","万一桑榆容倦翮，西飞会访毛公坛。"]},{"t":"铁笛道人新居曰书画船亭作诗以寄","f":"七言律诗","c":["苏州去访扬雄宅，近水楼居似月波。","东府官曹知者少，西山爽气望中多。","台招天上仙人凤，池养山阴道士鹅。","谁和淳风吹铁笛，莫愁艇子柳枝歌。"]},{"t":"寄杨廉夫郑明德","f":"七言律诗","c":["快雪时晴春意动，归舟移缆向方塘。","走寻饮伴鸡豚社，误落诗名锦绣场。","子云奇字谁能问，郑老襟期独不忘。","阖闾城中可终老，安得四万买沧浪。"]},{"t":"马伯庸中丞桐乡阡迁祔有旨赐碑名肇文开善有诗次韵","f":"七言律诗","c":["公家阡表似泷冈，总为能文补舜裳。","龙耳当承天子问，龟趺重表郑公乡。","异时将相宁无种，此举邦家亦有光。","想见丹书映丛桂，淮南无地著秋香。"]},{"t":"寄题陈渭叟紫云编用张仲举韵","f":"七言律诗","c":["葛溪观主陈渭叟，高行绝人诗益工。","明月双珠好奇服，閒居七言成变风。","大茅独立云在下，小史久住江之东。","吴筠寥寥五百载，唯我与君相长雄。"]},{"t":"新栗寄云林","f":"七言律诗","c":["朅来常熟尝新栗，黄玉穰分紫壳开。","果园坊中无买处，顶山寺里为求来。","囊盛稍共来禽帖，酒荐深宜蘸甲杯。","首奉云林三百颗，也胜酸橘寄书回。"]},{"t":"西爽轩次韵韩致用","f":"七言律诗","c":["大名谁及河东老，为爱幽轩肯赋诗。","沆瀣一杯凌倒景，阑干几曲带清漪。","徒闻东海投竿去，不似西山拄笏宜。","两岸菰蒲鱼鸟乐，系船犹带绿杨丝。"]},{"t":"答董子羽见寄","f":"七言律诗","c":["清都闻已住多年，鹤驾鸾骖与后先。","阊阖五云宫树暖，蓬莱初日羽衣鲜。","神仙翰墨唯皇象，史馆人材总孟坚。","天上春风如旧识，殷勤吹送寄来篇。"]},{"t":"寄渭清远记室","f":"七言律诗","c":["大石坠腰勤苦行，此生深愧老卢能。","雨留涧下三板水，苔卧窗间七尺藤。","清壑钟传晨放梵，云门诗到夜挑灯。","凭君试问龙河隐，政在钟山第几层。"]},{"t":"吴兴舟中","f":"七言律诗","c":["苕溪斫鲙腹偏腴，取酒乌程清若无。","最怜杨柳破二月，绝胜蛾眉游五湖。","船头濯足畏鱼淰，港口卸帆惊鸟呼。","林峦在处著舟楫，倘有剩田吾欲租。"]},{"t":"次韵倪元镇赠小山张掾史还寄元镇","f":"七言律诗","c":["为爱髯张亦痴绝，簿领尘埃多强颜。","何如膝上王文度，转忆江南庾子山。","绿树四邻悬榻在，青溪千仞荷锄还。","风流耆旧凋零尽，莫怪参军语带蛮。"]},{"t":"元统甲戌夏五月既望余客义兴王氏怀庆堂十又八日偕士友张德常谒张公洞得七言诗一首寄住山陈长卿周仁仲","f":"七言律诗","c":["路入秋阴罨画间，弭节洞灵俱启关。","东皇衣覆云雾海，玉女盆盛人鸟山。","牵骡步步迹石髓，投龙往往祝金环。","茅家小史岂尘土，此地一游聊解颜。"]},{"t":"吴石居使君寿八十","f":"七言律诗","c":["若翁腰带玉围虹，剩喜今年八十同。","食邑尝为骁骑尉，入城争识鹿门公。","车回晚望蓬莱日，帽卸凉梳菡萏风。","儿子去为真学士，未应园绮住山中。"]},{"t":"吴养浩江浙提学任满侍亲归番阳","f":"七言律诗","c":["稳送归帆向锦江，西湖能负白鸥双。","书中久已知梁鹄，床下时曾拜老庞。","封还画省文章印，盛取玉堂云雾窗。","荣禄乡中会耆旧，开筵应酿酒盈缸。"]},{"t":"题彭大年祷雨诗卷和仲举韵延祐己未开玄道院作","f":"七言律诗","c":["羽衣秋薄剪湘荷，茅屋山宫补绿萝。","白石资方青䭀饭，洪厓借乘雪精骡。","松云暖忆春游岳，冰草寒怜晓度河。","使节南归如见念，峰头笙鹤好相过。"]},{"t":"悼鹤","f":"七言律诗","c":["羽毛冻损雪襕斑，碧落游魂杳不还。","和靖船归笼尚闭，浮邱经在寿能悭。","长身被裹玄黄内，旧迹苔封紫翠间。","欲撰瘗铭修故事，寄书先报九华山。"]},{"t":"和实喇卜郎中上巳湖上道宫韵","f":"七言律诗","c":["望湖楼观似山阴，水边丽人同赏心。","槐火新泉还有梦，玉鱼葬地已无金。","三潭雨压蛟龙睡，半岭风传鸾凤音。","拟续临河修禊事，尘埃茧纸不堪临。"]},{"t":"代溪月翁和吴宗师所寄赐酒感兴诗韵","f":"七言律诗","c":["年年恩霈出皇家，此度仍回八月槎。","望阙苍龙分瑞霭，开樽白兽泻流霞。","笺天久已知心事，鉴水唯应换鬓华。","遥想新春供大礼，班头对御祝椒花。"]},{"t":"柳道传送别还茅山次韵复谢","f":"七言律诗","c":["乌蜀先生相见稀，钟陵初载橐书归。","江南萧艾作人立，卷里卢龙看雪飞。","最怜玉斧有道气，重惜子真犹布衣。","去去空山相忆夜，朱弦三叹为君挥。"]},{"t":"次韵题吕氏园馆","f":"七言律诗","c":["因向云间求二陆，西施浦口弄云沙。","东风勒住螭头舫，微雨催开茧粟花。","到处华房通曲密，旧时醉墨误欹斜。","一声歌板银瓶侧，亦见玉童双髻鸦。"]},{"t":"和坡仙寒食诗","f":"七言律诗","c":["寒食今年二月晦，又分新火到厨烟。","碧桃花落閒谁埽，白苧衣轻老更便。","发箧但馀金薤墨，考年正在玉堂编。","大书绝类颜光禄，小字骎骎逼墓田。"]},{"t":"再次韵实喇卜郎中春游二首 其一","f":"七言律诗","c":["杨柳三眠午未醒，杨花飞雪散星星。","海中蜃气春浮岛，月下胎仙夜降庭。","尺素书来云锦织，紫鳞跃处浪纹腥。","楼前政有三株树，剪断西山一半青。"]},{"t":"再次韵实喇卜郎中春游二首 其二","f":"七言律诗","c":["邻近桃源鸡犬家，不缘迷路得看花。","衣裳总湿三危露，服食唯消五色霞。","鹤冢浪磨崖上字，渔舟潮阁渡头沙。","石盘棋子都狼藉，莫向人间问岁华。"]},{"t":"欧阳巡尉遇仙卷","f":"七言律诗","c":["宝圭风洞鼓钲鸣，独挈仙壶一世惊。","勾漏丹砂还道术，泷冈阡表足家声。","芙蓉城小花周匝，枸杞丛深犬吠迎。","不上飙梯十二级，白头空愧学长生。"]},{"t":"伏蛟台胡道玄请题伯生有记","f":"七言律诗","c":["豫章自昔旌阳宅，借问仙都已劫灰。","西山应无剪柏处，东湖遂有伏蛟台。","千年铁札化为石，十日阴风怒若雷。","妖孽不生寰海静，五陵佳气待君来。"]},{"t":"浴鹄湾题壁","f":"七言律诗","c":["洑流乱石幽栖地，子美诗中萧史家。","白发羽衣元自称，风流异代不须嗟。","竹缘迮径篱编笋，丛碍低垣雨卧花。","岂少烟霞閒艇子，一枝聊赠老生涯。"]},{"t":"送姚焕章还京口兼简张率性","f":"七言律诗","c":["江乡人事凋讹尽，人日题诗复送行。","十载归来访邻里，他年科第属门生。","春泉暗动金沙井，晴雪微椷铁瓮城。","推官厅有诗人住，閒暇相求一寄声。"]},{"t":"和丹邱生悼吾子行书遗墨后","f":"七言律诗","c":["故人亦复葬江鱼，空向人间忆子虚。","月下箫閒留谱在，竹边房冷倩谁居。","蓬莱都水题金简，汲冢先秦见漆书。","惟有研山磨不朽，时时泪滴玉蟾蜍。"]},{"t":"八月十五夜待月","f":"七言律诗","c":["移床露坐閒临水，浴鹄湾头足芰荷。","秋已平分催节序，月还端正照山河。","老怜宋玉生悲思，狂忆桓伊作浩歌。","云汉茫茫一卮酒，白头惭愧古人多。"]},{"t":"次韵韩伯清见寄","f":"七言律诗","c":["尘海幽居似地仙，满床堆笏是家传。","座中桃李春风酒，郭外桑麻杜曲田。","倚盖一松扶偃蹇，影娥片月弄婵娟。","池边草色撩诗思，未觉才情让惠连。"]},{"t":"月山石诗","f":"七言律诗","c":["拾得金钱溪上石，小峰如弁立云根。","他山鸟道隔千里，新月蛾眉见一痕。","入林误踏金蟆背，激水犹思雪浪盆。","拟就漫郎呼酒舫，石鱼湖上共洼尊。"]},{"t":"春将过半病怀索莫惜无可与言诗者得句自遣山泽癯者云","f":"七言律诗","c":["一一花栽绕屋庐，半春多病意何如。","缘诗太瘦终无补，与酒全交渐要疏。","研席留香非长物，斋庖得笋是佳蔬。","鹤群呼唤来同饮，新绿溅溅已满渠。"]},{"t":"士弘贤良猥赠佳什空山真有似人之喜即与奉和所望为晚菊一来山也丙戌夏作","f":"七言律诗","c":["南州高士秪徐君，野鹤昂然自不群。","心似寒潭冰下水，身如秋岭雨馀云。","艺兰何待樵青斧，酾酒难寻李白坟。","为问别来能几日，城中消息了无闻。"]},{"t":"方泳道令尹水竹亭","f":"七言律诗","c":["水竹亭子在花山，输与幽人日倚栏。","苍雪四檐迷䆗窱，绿波三面浸琅玕。","扶行绿竹鸠形杖，濯足金沙鸭嘴滩。","几树甘棠同召伯，更留清节比方干。"]},{"t":"善权山洞","f":"七言律诗","c":["善权离墨争盘纡，浩劫磥砢仙人庐。","莘莘石林压水府，往往阁道通楼居。","壁藏已出黄素卷，穴处尤多青绿鱼。","爱此长连煮药灶，待我盥漱沾遗馀。"]},{"t":"次松瀑黄尊师寓筹峰韵","f":"七言律诗","c":["保大谁传墨半规，笔踪惊见十年迟。","风流丘壑真吾事，名教衣冠异昔时。","书别左公寻解剑，酒深东老独留诗。","谷山长在通玄顶，笙鹤相过自有期。"]},{"t":"快雨喜晴而开阳室适成赋诗自慰","f":"七言律诗","c":["春来耽酒仍耽困，一枕雨声如蜜甜。","老锸栽松宁有待，饥肠食笋独无餍。","峰连笔格安空翠，泉入茶垆斗谷帘。","吾爱吾庐聊复尔，少留佳日在茅檐。"]},{"t":"女仙江静真碧游仙词","f":"七言律诗","c":["衣剑符图有子传，生如孤凤蜕如蝉。","方留橘叶聊供母，谁信桃枝已得仙。","萧索帘帏通素月，玲珑环佩曳空烟。","麻姑坛上花姑老，想共乘鸾欲著鞭。"]},{"t":"越灵峰寺之松风阁","f":"七言律诗","c":["溪谷风声何瑟瑟，啸歌长在两长松。","金鸡翔舞不多见，青壁夤缘知几重。","花时扫阁黄尘满，泉处凿厓甘露浓。","待我与携笙鹤去，香炉对面礼陶峰。"]},{"t":"笔冢","f":"七言律诗","c":["退笔如陵那忍弃，敛藏数笼瘗岩阿。","管裁犀象宁同殉，研历冰霜尚可磨。","兔窟早空金椀地，鹅峰深润墨池波。","毛颖有灵应感遇，秦恩自少主恩多。"]},{"t":"次桑善止韵是日廉夫杨尹见访","f":"七言律诗","c":["发脱冠欹衰态多，日长犹赖饮无何。","阿对泉头布衣老，谢公墩上美人过。","青松岂代麈尾柄，如意莫击珊瑚柯。","挍书天禄馀事耳，迟子考槃同涧阿。"]},{"t":"次韵王文友送游张公洞","f":"七言律诗","c":["庚桑成道来孟峰，再拜摄衣升故宫。","馨香果核犹可拾，颠倒云气长相蒙。","有时月明钟磬发，绝顶涛声舟楫通。","看从便道之五岳，腰插骡鞭追老翁。"]},{"t":"再次倪元镇韵","f":"七言律诗","c":["嗜石未数奇章公，太湖洞庭无此峰。","便拟翻身入青壁，谁见抱膝哦长松。","乳香从令飞鼠饮，绝路或与樵人逢。","玉女下房不可到，只许云气随飞龙。"]},{"t":"黄一峰画贞居图","f":"七言律诗","c":["北苑南宫凝绝笔，蟠胸磊磈若为裁。","按图宁在多多许，落墨真成滚滚来。","百折丹梯凌涧道，一川燄水动湾洄。","时清谁问商于路，乞我西山锦绣堆。"]},{"t":"代玄览真人次虞伯生见寄韵","f":"七言律诗","c":["屋倚松杉路拥莎，金鳌小隐且婆娑。","几年有约遥相望，一棹何时肯见过。","老去山中空岁月，秋来江上政风波。","黄花满眼香醪熟，对此其如逸兴何。"]},{"t":"又次韵","f":"七言律诗","c":["别后惊心岁已驰，几回草梦绕春池。","新诗远寄迢遥驿，旧约重看绝妙碑。","鳌禁风清班缀玉，龟溪雪冷鬓垂丝。","何时共执论文酒，坐对西窗待月迟。"]},{"t":"赠姜彦翁秀才","f":"七言律诗","c":["科举恩沾乡贡榜，学校例贡诸生员。","多岐取士从润色，百骸受蠹争夤缘。","穷巷授徒缺养母，普天为吏横索钱。","妙年立身在择术，老生常谈无弃捐。"]},{"t":"和黄晋卿提举忆旧诗","f":"七言律诗","c":["支许何能接王谢，山阴图画略相同。","能留茧纸真奇事，爱养鹅群少道风。","苔树斲冰春未破，花瓷削雪酒如空。","深惭故旧相料理，肯使牢愁坐五穷。"]},{"t":"天师素华阁","f":"七言律诗","c":["仙家楼阁风尘表，更筑凌空月榭高。","虚白岂知存夜气，太清还许隔秋毫。","溪光澹澹冰填壑，松响离离雪舞涛。","此去银桥通咫尺，神仙直下有灵鳌。"]},{"t":"碧筒饮","f":"七言律诗","c":["采绿谁持作羽觞，使君亭上晚樽凉。","玉茎沁露心微苦，翠盖擎云手亦香。","饮水龟藏莲叶小，吸川鲸恨藕丝长。","倾壶误展琳琅袖，笑绝耶溪窈窕娘。"]},{"t":"上京赐宴王眉叟有诗次韵","f":"七言律诗","c":["从事何缘过草堂，行都遣赐玉壶方。","远劳使者红尘骑，烂煮仙家白石羊。","中圣敢辞千日醉，承恩独许四明狂。","金茎剩有三清露，润及葵心向太阳。"]},{"t":"古诗十首 其一","f":"五言古诗","c":["不爱昆冈玉，不爱江汉珠。","爱己有苍璧，有之利有馀。","吾生为我有，其利当何如。","论爵不足贵，论富不能踰。","达生命之情，顺生以自娱。"]},{"t":"古诗十首 其二","f":"五言古诗","c":["荆人有遗弓，索之将奚为。","且荆人遗之，乃荆人得之。","孔子闻之曰，去其荆可耳。","老聃闻则曰，去其人可矣。","天下有至公，孔聃得其理。","天地且弗有，莫知其所始。"]},{"t":"古诗十首 其三","f":"五言古诗","c":["墨子叹染丝，所叹一何长。","染于苍则苍，染于黄则黄。","奚独染丝然，染国在所当。","有染如伊皋，禹汤称圣王。","殷纣染恶来，既染国亦亡。","染士如孔聃，死久道弥光。"]},{"t":"古诗十首 其四","f":"五言律诗","c":["鲁君聘颜阖，踰垣避使者。","我非恶富贵，君胡独不舍。","全生以为上，迫生以为下。","当知得道人，治国其土苴。"]},{"t":"古诗十首 其五","f":"五言律诗","c":["虞人百里奚，所鬻五羊皮。","有得其说者，乃是公孙枝。","献诸秦穆公，四境不足治。","贤者倘不遇，后世谁当知。"]},{"t":"古诗十首 其六","f":"五言古诗","c":["昔者齐桓公，往见小臣稷。","一日凡三至，欲见且弗得。","骜爵固轻主，骜霸亦轻士。","大夫纵骜爵，骜霸吾敢尔。","所以终见之，不为从者止。","谁云内行缺，论霸亦可矣。"]},{"t":"古诗十首 其七","f":"五言古诗","c":["桓公遇宁戚，饭牛中夜起。","赐之以衣冠，一说境内理。","再说为天下，桓公以师事。","卫与齐不远，安用疑客子。","不患有小恶，所患亡大美。","且人固难全，用长当若此。"]},{"t":"古诗十首 其八","f":"五言律诗","c":["业烦则无功，礼烦则不庄。","令苛则不听，禁多则不行。","国人逐狡兔，因之杀子阳。","严刑无所赦，适见召乱亡。"]},{"t":"古诗十首 其九","f":"五言古诗","c":["齐有善相狗，假买取鼠者。","数年不取鼠，畜之不如舍。","相曰实良狗，志在獐麈鹿。","欲观取鼠能，请桎其后足。","桎足乃取鼠，淹尔骥獒气。","安得忘言徒，喻此鸿鹄志。"]},{"t":"古诗十首 其十","f":"五言古诗","c":["燕雀争善处，处在大屋下。","姁姁甚相乐，子母得相哺。","一朝灶突决，火炎屋栋燬。","燕雀色不变，不知祸及己。","人臣私聚敛，迷国坏纲纪。","孰谓斯人智，不如燕雀耳。"]},{"t":"独酌","f":"五言古诗","c":["静极忽不惬，掩书曝前轩。","荣木樊四维，时禽托孤园。","群物方趋功，吾衷恒晏然。","本乏超世才，偶脱区中缘。","妙理寄浊醪，嘉名爱灵仙。","从吾所好耳，富贵须何年。"]},{"t":"天池石壁为铁雅赋","f":"五言古诗","c":["尝读枕中记，华山閟中吴。","神泉发其颠，青壁缭其隅。","春风四山来，群绿互纷扶。","羽觞曲折行，浮花与之俱。","采珠搴薜荔，洗玉弄芙蕖。","聱叟颇好名，石洼作鱼湖。","鸿乙志草堂，挑烟遂成图。","而此涤烦矶，阅世如摴蒲。","发兴云林子，盥手与我摹。","居然缩地法，挈入壶公壶。"]},{"t":"游虎邱次东坡先生韵","f":"五言古诗","c":["日出东海头，虎气踞兹岭。","渴心望气往，解后辘轳井。","宁若军中拜，奔泉酬老耿。","莽邱专鬼物，阴壑杂蛇黾。","鱼肠卧池底，百鍊岂重矿。","以问神物化，后日属吴猛。","怪蟒既血刃，大道孰争骋。","我行须人扶，鸠杖惭祝哽。","小吴不满眼，坐纳三万顷。","化国方日长，霸业久灰冷。","淞水翰归吴，过溪柳迁永。","吾非斯人俦，短句惜流景。","茶烟寄禅榻，弄我鬓丝影。","散人初无号，奚必烦上请。"]},{"t":"次倪元镇游虎邱","f":"五言古诗","c":["振屐稍践危，援藤遂支滑。","尚馀金玉气，山川相应发。","沼吴不满眼，轩中树如发。","花覆阖闾城，石绕生公榻。","适与幽人携，及兹暮春月。","坐久得忘言，移䩳荫清樾。"]},{"t":"答寄笋蔬","f":"五言古诗","c":["远寄玉山篇，来自故人庐。","竹萌且柔弱，荻笋亦丰瘦。","姜醯助芳辛，浊醪为前驱。","猪肝恐累人，我亦仲叔徒。","念此风雨中，江外致嘉蔬。","柬诗答幽意，老饕良可吁。"]},{"t":"冬夜震泽风雪异常","f":"五言古诗","c":["晴燠不可恃，一夕冬令变。","屡忘和煦恩，惟曰祈寒怨。","老屋雪没隙，广泽风肆便。","反覆鼓洪涛，扬簸塞荒堑。","隐然洞庭乐，勇盛阖闾战。","万物刍狗如，埋没加蹂践。","凌晨枉严冱，野日复葱茜。","仁哉天地心，观复斯可见。"]},{"t":"上方教寺","f":"五言古诗","c":["橘林千黄金，林静路逾僻。","忽临消夏湾，云海浩如积。","绮季不可追，空馀骐骥迹。"]},{"t":"赠倪元镇","f":"五言古诗","c":["庞公有名言，鱼鸟托栖止。","而其遗子孙，亦在安而己。","子有丘壑趣，文弱与时背。","强梁方蛇吞，贪黩亦虎噬。","何以犯多难，适为田业累。","深泥没老象，自拔须勇志。","连环将谁解，旦暮迭兴废。","所以明哲徒，置身兴废外。","贤者蘧伯玉，知非复何悔。"]},{"t":"夕佳楼","f":"五言古诗","c":["西山朝气爽，南山夕气佳。","朝爽人共忻，夕佳吾所怀。","山僧阅世久，结庐深避乖。","蕙楼将对峙，菌阁亦双排。","维南列崇阜，不受烟岚霾。","我亦迟暮人，心迹倦鸟偕。","兹焉记高躅，庶与静者谐。"]},{"t":"过太湖","f":"五言古诗","c":["溔㵿鱼龙戏，僻侧凫雁宿。","并吞三万顷，宁不为小曲。","唯应鸱夷子，曾泊西山麓。"]},{"t":"毛公坛","f":"五言古诗","c":["方坛荫奇竹，俨彼毛骨秀。","想见黄眉公，时来濯冰溜。","一往不可得，尚问何日又。"]},{"t":"黄公泉","f":"五言古诗","c":["黄公鍊药处，遗井兹邱上。","何年一泓碧，褒博照容状。","不意樵者歌，犹闻紫芝唱。"]},{"t":"华山寺三泉","f":"五言古诗","c":["寺以华山名，一一灵泉泻。","会昌旧文字，毁壁存牖下。","往劫莲花开，曷以信来者。"]},{"t":"奔月卮歌荅铁雅所作","f":"七言古诗","c":["甓社明珠奔入月，脱壳政似风蝉洁。","渔网出之不敢视，涤尽含沙光不灭。","文昌四星吞在腹，一一金晶大如菽。","蜃物还来作饮器，日夜雄雌绕林屋。","一扇桃核宽有馀，半叶蕉心卷未舒。","饮非其人跃入水，怪雨盲风生坐隅。","置之天上白玉盘，斗柄挹酒长阑干。","李白跳下鲸鱼背，持劝我饮相交欢。","幽宫冯夷为予泣，酌尽海水百怪出。","还我平生老蚌胎，许君醉卧鲛人室。"]},{"t":"悼薛玄卿","f":"曲","c":["玄卿难再得，本是餐霞人。","高怀独超物，洞鉴亦绝伦。","君自江东我吴下，早岁联翩侍金马。","御榻赐书凡一束，仙苑偷桃动盈把。","紫虚元君之玉诀，青城先生教我者。","感君多道气，探怀为君写。","学士承旨平原公，许我与君扬□同。","一时标名两外史，羽衣白茅立下风。","我还句曲廿馀载，君乘輶轩历烟海。","归锦桥西结草楼，楼中袱被长相待。","风烟山水共追寻，福临洞口话离心。","年深书字化为碧，白首苍茫成古今。","圣井山崩数千尺，君从群龙去无迹。","困顿盐车筱岭头，此日思君复何益。"]},{"t":"玉笙谣为铁门笙伶周奇赋","f":"曲","c":["我有紫霞想，爱闻白玉笙。","县匏比竹无灵气，昆邱采此十二茎。","凤咮衔明珠，凤翼排素翎。","金华周郎妙宫徵，子晋仙人初教成。","月下吹参差，群雏亦和鸣。","缑氏山头白云起，七月七日来相迎。","长谢时人一挥手，飘下满空鸾鹤声。"]},{"t":"奉赠鲁学士","f":"七言律诗","c":["阁道如珠环太极，天风浩荡曳天裾。","云行龙尾随金仗，日照螭头侍玉除。","四海声华周典礼，一时人物鲁璠玙。","愿臻咸际无为化，宁读人间非圣书。"]},{"t":"凤皇山怀古","f":"七言律诗","c":["江右夷吾浪得名，豫州英槩亦沉冥。","夕阳枯木山如赭，秋雨荒台草自青。","汉苑玉鱼谁复葬，昭陵石马亦无灵。","可怜白发商人妇，犹向灯前话后庭。"]},{"t":"题西湖何氏隐真馆","f":"七言律诗","c":["鸡犬云中豹一斑，路邻仙冢昔跻攀。","说经僧去黄龙卧，负药童归白鹤闲。","酒仰秫田陶令宅，井分丹水葛洪山。","不因草结昭台约，此地从知几往还。"]},{"t":"次孙大方仙兴诗韵","f":"七言律诗","c":["仙仗来时瑞雾屯，真人玉女侍灵轩。","亭亭珠穗香烟直，烂烂槫桑玉色温。","华雨扫尘鸾帚湿，岛云承袜蜃楼昏。","至今星斗天坛夜，望拜青都虎豹门。"]},{"t":"送人之茅山","f":"七言律诗","c":["桃竹齐眉草屦柔，江云湿重木绵裘。","茅山一去五百里，楚月相望十二楼。","林下甑香黄独月，松根锄冷茯苓秋。","药瓢料得归来满，多病微躯我亦求。"]},{"t":"题桐柏观","f":"七言律诗","c":["百折丹梯杪万松，凤笙台殿赤城钟。","亲从海上求司马，宁复山中起卧龙。","琼阙排云窥坐席，银桥乘月认仙踪。","真人及此东行日，笑说卢敖向九峰。"]},{"t":"鹤冢","f":"七言律诗","c":["鹤寿千年定有无，羽衣蝉蜕雪模糊。","樵人与裹玄黄帔，少保亲传粉墨图。","坯土未乾青草短，三山何在白云孤。","夜寒蕙帐应岑寂，初向华嵩觅凤雏。"]},{"t":"雨怀郭子昭御史","f":"七言律诗","c":["洞户霾云昼不开，大茅南面水萦回。","深山此日蛟龙喜，旧雨故人骢马来。","涧道浮槎高寄树，石幢阴篆湿生苔。","销愁底用金陵酒，剩引洼尊枕瀑雷。"]},{"t":"寄倪元镇","f":"七言律诗","c":["雨天初寒雪复作，春风相欺何太颠。","谁依井灶皆兽迹，独拥书册犹鸢肩。","枸杞埋根乍难斸，樱桃放花殊可怜。","贺监宅前旧游处，快放柳条维酒船。"]},{"t":"次韵元镇见寄","f":"七言律诗","c":["衣桁常容蛛网悬，石床浑让女萝牵。","道术何烦孔郎祀，屋庐政用郤超钱。","泉崩涧底归樵路，雨压厨头蒸术烟。","谁见西邻拆书后，一枝风竹鹁鸠眠。"]},{"t":"怀茅山","f":"七言律诗","c":["我有草堂南洞门，常时行坐虎同群。","丹光出林掩明月，玉气上天为白云。","遥忆田泉洗苍术，更思陶涧采香芹。","归来闭户偿高卧，莫遣人书白练裙。"]},{"t":"题元章研山图","f":"七言律诗","c":["南宫米老书无敌，同盟亦有薛河东。","研山自昔怀清赏，石友令人拜下风。","华盖天坛承露洁，月岩空洞与天通。","绝怜古学龟城叟，一一题诗取次工。"]},{"t":"梅雪斋雅集分题得酒香","f":"七言律诗","c":["醲郁芬香味更严，瓮间飘满读书帘。","绝胜金鸭薰花气，错认山蜂酿蜜甜。","三嗅初令消渴止，一中定扫宿酲淹。","醉翁鼻观还亲切，不待狂僧写布帘。"]},{"t":"折莲花寄韩伯清","f":"七言律诗","c":["丈八河沟锦作堆，一花初照夜明苔。","濯缨歌向沧浪去，执盖郎从碧落来。","天水染云如净练，露盘餐玉似空杯。","韩家公子多才思，乞与香奁相对开。"]},{"t":"水竹居为湖州沈自诚赋","f":"七言律诗","c":["我爱苕溪溪上居，琅玕千个绕吾庐。","早知竹叶仙舟梦，合误榴皮醉墨书。","屋底煖云蒸汗简，月中清露滴方诸。","邻家已订浮家约，乞我长竿学钓鱼。"]},{"t":"次韵荅吴兴黄伯成","f":"七言律诗","c":["行尽松阴黄叶株，三叉路口问茅庐。","青山对语惟扪虱，落日催归独跨驴。","土木形骸嵇叔夜，波澜文字木玄虚。","残年记得相存问，莫道天寒无鲤鱼。"]},{"t":"过吴兴谒赵承旨","f":"七言律诗","c":["两岸人家洲渚生，满城山色与溪声。","船过鸥边掠浮玉，云移木末见飞英。","书淫画圣王孙老，雪霁沙晴湖水清。","洞经不用鹅群换，也许山阴道士迎。"]},{"t":"松花饼","f":"七言律诗","c":["怪来粔籹作鹅黄，浑是苍髯九粒香。","甜味中边唯食蜜，苦心早晚待休粮。","仙人骐骥留看取，道士嵩阳远寄将。","笑比红绫春餤巧，齿牙根底嚼糖霜。"]},{"t":"赠别休休庵了堂上人","f":"七言律诗","c":["老僧十年不出户，袈裟搭架风披披。","祖衣留在阿兰若，佛法传过高白丽。","客床雪练一瓯茗，经藏苔昏三尺碑。","不向旧房看偃盖，卷中原有古松枝。"]},{"t":"宿玛瑙寺","f":"七言律诗","c":["一宿葛洪丹井上，化为蝴蝶梦魂清。","湖田凉蛤四骰吠，烟寺晓钟相递鸣。","孤屿横陈为玉几，初阳焕烂似霞城。","拿舟又入水云去，还我风篁雪窦声。"]},{"t":"寄欣笑隐","f":"七言律诗","c":["翻经台畔惜分携，华盖峰前几梦思。","一席地分眠鹿草，三更月在挂猿枝。","我书安能半袁豹，君才端倍十曹丕。","上番画逢虞秘监，不嫌频窜仰山碑。"]},{"t":"大涤山","f":"七言律诗","c":["此峰屹立浩无前，信是人间别有天。","铜柱何烦天北际，蓬山宁在海东边。","采樵巨箬多无骨，捣药灵禽或是仙。","老我不能为狡狯，峰头看月几回圆。"]},{"t":"丹泉","f":"七言律诗","c":["涵渟万象一泓中，欲探灵源未易穷。","丹窖久埋泉眼赤，珊瑚长浸石头红。","评来水味羞扬子，收取沙床赠葛洪。","一醉流霞三万日，年年分给羽人宫。"]},{"t":"天池楼","f":"七言律诗","c":["天池一楼小如架，檠出半天天雨华。","山围丈石狮子座，寺属三朝母后家。","时呼白猿听奇句，亦许飞仙餐紫霞。","我来把断朗风口，只留床角置袈裟。"]},{"t":"牧之水榭","f":"七言律诗","c":["爱此招提绝世氛，何因水榭得名闻。","幽篁嘉木知谁共，尘意云情若个分。","阳羡溪头黄叶路，晚晴赋里白鸥群。","诗僧文采居然别，解道曾留杜使君。"]},{"t":"同张德常游张公洞","f":"七言律诗","c":["骑入秋云罨画间，日出洞灵犹启关。","东皇衣覆云雾海，玉女盆盛人鸟山。","牵骡步步踏石髓，投龙往往祝金环。","茅家小吏向尘土，弭节相迟明当还。"]},{"t":"题赵松雪怡乐堂图","f":"七言律诗","c":["幽人结屋傍江干，怡乐名堂只数间。","黄鸟隔帘诗梦醒，紫鳞供馔钓舟还。","檐前景色春常在，柳外柴门昼不关。","谁识个中真乐处，陶然天地一身闲。"]},{"t":"马塍新居","f":"七言律诗","c":["浮家泛宅意何如，玉室金堂计未疏。","归锦桥边停舫子，散花滩上作楼居。","澹然到处自凿井，玄晏闭关方著书。","但得草堂赀便足，人间何地不樵渔。"]},{"t":"西湖放灯","f":"七言律诗","c":["共泛兰舟灯火闹，不知风露湿青冥。","如今池底休铺锦，此夕槎头直挂星。","烂若金莲分夜炬，空于云母隔秋屏。","却怜牛渚清狂甚，苦欲燃犀走百灵。"]},{"t":"云巢楼","f":"七言律诗","c":["初阳台上白云多，云里层层玉树歌。","栖息一枝缘未稳，飞翻干仞奈危何。","雨中幕燕雷惊起，峰顶笙鸾目送过。","好在丹梯无百尺，屋头看尽白鸥波。"]},{"t":"罗姑洞","f":"五言绝句","c":["苍梧眇天末，闻有绿毛仙。","却过华阳路，人间九百年。"]},{"t":"题拜石图","f":"七言绝句","c":["一代清狂海岳老，世间簪绂更须论。","却怜种放樵夫拜，不到奇章宰相门。"]},{"t":"来鹤亭","f":"七言绝句","c":["华表归来旧令威，晓风将梦上天飞。","缑山借与浮邱伯，一曲瑶笙月下归。"]},{"t":"来鹤亭即席赋","f":"七言绝句","c":["草堂孤鹤驻樊笼，忽有鸾笙下碧空。","待唤羽衣相向舞，吕家园里看春风。"]},{"t":"题鹤亭所藏马图","f":"七言绝句","c":["九霄天马俱龙种，四十万蹄云锦斑。","一自渔阳鼙鼓后，不知几个到骊山。"]},{"t":"苕溪草堂","f":"七言绝句","c":["传语幽人范叔豹，雾隐何时窥一斑。","天下草堂随处取，无此玉湖浮玉山。"]},{"t":"吴兴道中四首 其一","f":"七言绝句","c":["晴港阴塍乳犊眠，凉风绿鬓飏缲烟。","埋名惭愧芦中老，坐阅江湖逆顺船。"]},{"t":"吴兴道中四首 其二","f":"七言绝句","c":["风捲湾埼半折蒲，意行弄水不嫌迂。","笔床正掠鹅群过，疑杀山阴染翰图。"]},{"t":"吴兴道中四首 其三","f":"七言绝句","c":["眠溪大树不见日，牧鹅小儿兼钓鱼。","南风相送玉湖口，舟子饭时吾读书。"]},{"t":"吴兴道中四首 其四","f":"七言绝句","c":["扁舟偶趁采樵风，题扇书裙莫恼公。","何处人间无六月，碧澜堂上雨声中。"]},{"t":"鲤鱼","f":"七言绝句","c":["桃花鳜鱼世常有，莼菜鲈鱼浪得名。","试吃江南鲤鱼尾，侯家无此一杯羹。"]},{"t":"题授经郎献书图","f":"七言绝句","c":["侍书爱题博士画，日日退朝书满床。","奎章阁上观政要，无人知有授经郎。"]},{"t":"次韵刘师鲁吴山清晖亭三首 其一","f":"七言绝句","c":["凤去箫韶空隐隐，鹤栖台殿旧层层。","浮屠立尽千秋雪，谁倩风铃说废兴。"]},{"t":"次韵刘师鲁吴山清晖亭三首 其二","f":"七言绝句","c":["万瓦连云人世空，一鸡啼日海波红。","欲窥倒影清溟外，故著危亭紫翠中。"]},{"t":"次韵刘师鲁吴山清晖亭三首 其三","f":"七言绝句","c":["故山茅屋破仍欹，惆怅西风日夜吹。","今日偶来高处望，严家亭上立多时。"]},{"t":"初阳台","f":"七言绝句","c":["初阳台上新亭好，一曲笙簧石壁开。","惊起玄真狂道士，步虚飞下玉清台。"]},{"t":"西湖竹枝词","f":"七言绝句","c":["光尧内禅罢言兵，几番御舟湖上行。","东家邻舍宋大嫂，就船犹得进鱼羹。"]},{"t":"赠笔生沈君实","f":"七言绝句","c":["玉堂弄翰青钱选，闻道吴兴屡出奇。","何事君家苔藓壁，醉仙留句只榴皮。"]},{"t":"揭学士过武康山中十日薛外史江东未至二首 其一","f":"七言绝句","c":["南镇行香揭夫子，歇马走入计筹山。","杜尊师去白石在，翻动琳琅翰墨间。"]},{"t":"揭学士过武康山中十日薛外史江东未至二首 其二","f":"七言绝句","c":["一杯爱渠蒸蕨香，一槃劝我苦笋凉。","饱食翻疑得诗瘦，不如顿顿地椒羊。"]},{"t":"宿天申宫二首 其一","f":"七言绝句","c":["借渠灵坛一枝竹，穿云度险不须扶。","为寻石榻萝衣字，执火照遍青珊瑚。"]},{"t":"宿天申宫二首 其二","f":"七言绝句","c":["药苗松菌红斑斑，点缀风烟俎豆间。","篮舆三日半醒醉，春云只恋铜官山。"]},{"t":"学诗斋联句","f":"五言古诗","c":["明良赓歌基，猗那奏鼓始。","清庙殊雍雍，赤舄固几几。","岂惟缁衣贤，政以朱襮美。","原鸰兄弟急，河鲂父母迩。","便施谷中葛，亦采体下菲。","咏桑表沃若，歌莱赋乐只。","鲍谮苏公绝，厉怀凡伯耻。","思鸣卷阿凤，愿绘衮衣蜼。","蔽以思无邪，毋曰鼠有体。","言超授简贡，道在过庭鲤。","遂去文辞害，亦屏训诂眯。","谲谏主风刺，昌言发兴比。","雅亡继麟笔，和寡续巴里。","镐罢鱼在藻，屈倡凫汎水。","縆弦谁与奏，补苴自难拟。","哀哀河梁别，堂堂沛风起。","祠雒悔心萌，决虞壮图已。","塞瓠恨茀郁，援桂慄藿蘼。","便啼城上乌，犹恨水中沚。","隆中抱膝想，许下横槊伟。","体要必中度，葩正悉循理。","响当贯珠串，辍始辏车轨。","清圆斲冰苦，颖脱扣钟喜。","无题白乃圣，有作甫良史。","险如横空盘，突若破阵褫。","雕锼百神困，策役万象靡。","爨桐声玉明，庙乐厌石齿。","挥毫既凌厉，赋物斯须委。","郯公学方笃，吴歈好诚鄙。","萧斋扁佳名，华构落新址。","诗律妙独造，吏尘净一洗。","瑰辞出语阱，遗经贮腹笥。","道在用服形，神悟为洗髓。","不亏素王造，信全幽人履。","肾胃苦搯擢，物累困成毁。","直登陶韦奥，旁摩鲍谢垒。","燄凌天策燉，古偕灵光岿。","请验百世传，致慎一匮圯。","两老皆苦心，六义始盈耳。","挂一真漏万，聊以示吾子。"]},{"t":"旧有汉铜洗一作碧玉色受水一斗后有赠白石上树小芭蕉吾因置洗中名曰蕉池积雪彷佛王摩诘画意赋诗一首群公时多次韵仅存师鲁二篇","f":"七言律诗","c":["洗玉之池割圆峤，上有玉苗甘露零。","雪山凝寒压太白，海气正绿洒帝青。","是身非坚须长物，绝境无梦遗真形。","宁令严霜凋翠草，讵胜失水哀铜瓶。"]},{"t":"耕渔轩","f":"五言古诗","c":["幽人薄世荣，耕渔夙所喜。","朝耘西华田，莫钓洞庭水。","浮湛干戈际，无誉亦无毁。","酿秫云翻瓮，鲙鱼雪飞几。","客来具杯酌，客去味经史。","缅怀清渭滨，何如鹿门里。","往者不复见，斯人亦云已。","努力勤所业，庶免素餐耻。"]},{"t":"题墨兰","f":"七言绝句","c":["滋兰九畹空多种，何似墨池三两花。","近日国香零落尽，王孙芳草遍天涯。"]},{"t":"题赵仲穆竹西图为杨元诚","f":"五言律诗","c":["问讯扬雄宅，深居在竹西。","风林宜月影，春日听莺啼。","东老应同乐，南邻忆旧题。","东风又花草，相与友幽栖。"]},{"t":"酬虞道园","f":"七言律诗","c":["一函真箓是遗书，想为焚香谢紫虚。","海上安期分食枣，人间长史合县车。","泥丸日月存思否，华盖烟岚笔札馀。","绝叹清诗不埋没，解随霜叶堕山居。"]},{"t":"中庭古柏","f":"七言律诗","c":["庭中异柏前朝物，铜柯石干兀青苍。","云壑终忆老蛟卧，珠树独留威凤翔。","月上团阴移覆砌，雨馀古香飘近床。","支离疏者深根在，阅尽世人还久长。"]},{"t":"驯鹭","f":"七言律诗","c":["孑然驯鹭雪霜明，下濑求鱼自在行。","碧玉灯檠双足瘦，白麻衣袂一身轻。","海鸥见事应何晚，凡鸟题门也不情。","输我鸳行旧俦侣，举头寥廓总云程。"]},{"t":"题雪景三香图二首 其一","f":"七言律诗","c":["春雪无声入画堂，东风浑似北风凉。","祗缘何逊题诗少，信是徐熙落墨强。","青鸟下迎罗袜步，苍髯来近玉台妆。","匡庐也入幽闺梦，睡里山花各自香。"]},{"t":"题雪景三香图二首 其二","f":"七言律诗","c":["雪羽飞来雪意浓，国香狼藉暝烟丛。","倩谁与剪吴淞水，爱尔能吟柳絮风。","翠袖佳人玉跳脱，平头奴子锦薰笼。","剑南画手看前辈，着粉施朱或未工。"]},{"t":"挽贡正甫经历","f":"七言律诗","c":["亲闱晚岁斑衣乐，莲幕秋风绿水香。","范氏清名满吴会，朱公遗爱在桐乡。","淮山招隐推奇逸，彭泽疏封尽显扬。","却忆去年称寿日，刘梅盛事播诗章。"]},{"t":"龙翔大师秋后惠蕲簟","f":"五言律诗","c":["遮眼群峰雨，惊秋一叶风。","僧归建邺寺，诗到豫章公。","鲑菜真堪恋，桃笙不待攻。","澡身方得计，瓶外有馀空。"]},{"t":"次韵寄荅云门断江禅师","f":"七言律诗","c":["长眉如雪眼浑遮，施食岩前坐暝鸦。","坏衲半堆黄木叶，好峰千朵碧莲花。","湖山近日重来鹤，池馆于今足吠蛙。","早晚越中寻贺老，千秋观在尔东家。"]},{"t":"送太祝陈柏□还京师","f":"七言律诗","c":["公子翩翩出太常，南来使节拥辉光。","制器上供清庙荐，聚书内还东壁藏。","天禄子云终识字，岁星方朔暂为郎。","海沤零落洞庭野，回首箫韶引凤凰。"]},{"t":"龙虎山张一元一宿而去","f":"七言律诗","c":["神翁观主来相访，既去犹如梦见之。","闭户著书吾党事，对床听雨昔人诗。","万羊何与分忧责，一物终能系盛衰。","回首孤云自天末，竹阴凉坐看蛛丝。"]},{"t":"游惠山寺","f":"七言古诗","c":["水品古来差第一，天下不易第二泉。","石池漫流语最胜，江流湍激非自然。","定知有锡藏山腹，泉重而甘滑如玉。","调符千里辨淄渑，罢贡百年离宠辱。","虚名累物果可逃，我来为泉作解嘲。","速唤点茶三昧手，酬我松风吹兔毫。"]},{"t":"赠龙门恩公","f":"七言绝句","c":["恩公昔住天平日，林下相迎坏色袍。","行到龙门无脚力，右肩偏袒吃樱桃。"]},{"t":"喜春来","f":"曲","c":["江梅的的依茅舍。","石濑溅溅漱玉沙。","瓦瓯蓬底送年华。","问暮鸦。","何处阿戎家。"]},{"t":"游龙井方圆庵阅宋五贤二开士像","f":"五言古诗","c":["独寻招提游，果得世外欢。","昔贤所栖集，画像藏屋端。","山僧启锁鱼，不待啜茗乾。","修广各异制，精采俱生完。","堂堂苏长公，英气邈难干。","筇杖紫道服，天风吹袖宽。","清献薄须眉，示我铁肺肝。","尚馀所施物，片石椭而寒。","侍郎胡金华，高括侍中冠。","眉间可容掌，手版出中单。","颍滨与淮海，秋色亚层峦。","参寥独缁衣，颔髭茁茅菅。","最后辨才师，文茵高座安。","空山一室内，举目皆龙鸾。","再拜倾挈壶，喜极重悲酸。","去之三百载，归路何漫漫。","斯人为列星，下视虫沙繁。","宁不念学子，道术救彫残。","抵舍亟摹貌，微哉难控抟。","梦中傥未遇，展诗时一观。"]},{"t":"无波古井水","f":"五言古诗","c":["古井何泓然，不食自甘冷。","去来绝攀缘，挽断辘轳绠。","唯有中宵月，圆中时照影。"]},{"t":"清权尊师集中览庚戌见怀一诗感念今昔自伤之情","f":"五言律诗","c":["天既劳我晚，不如早息我。","奚止七不堪，于世无一可。","空山酒半瓢，秃发花三朵。","平生仲长统，谁能曲如锁。"]},{"t":"种树","f":"五言古诗","c":["植梓五十本，移松八百栽。","山灵借好雨，似为道人来。","青意争郁勃，细声亦吹洒。","松如稚子长，梓长未盈把。","吾衰讵能待，将以荫来者。"]},{"t":"三月十三夜对月","f":"五言古诗","c":["幽篁不见天，况乃见月色。","晴来春尚佳，岂不有馀日。","离离花气上，稍稍帘阴直。","啼鴂夜不眠，声欲碎岩石。","闻声思逾寂，悟赏在兹夕。"]},{"t":"独行","f":"五言古诗","c":["春泥未成沙，曳屣柔且平。","春风不鸣条，振衣凉且轻。","我意本静惬，中林便独行。","松盖无曲影，水乐皆全声。","踽踽迫前冈，悠悠度斜坑。","老樵眼如猫，见我不问名。","直赠金光草，疑是古先生。"]},{"t":"倪元镇玄文馆会饮","f":"五言古诗","c":["亲知贵浃密，屡此良宴会。","堂陛自崇广，促席归卧内。","说诗盛使气，屈折高李辈。","更端辄笑谑，知节已沾醉。","玲珑檐花乱，萧屑风竹碎。","政使韩伯休，移床夜相对。"]},{"t":"听雨楼","f":"七言律诗","c":["雨中市井迷烟雾，楼底雨声无著处。","不知雨到耳边来，还是耳根随雨去。","好将此语问风幡，闻见何时得暂閒。","钟动鸡鸣雨还作，依然布被拥春寒。"]},{"t":"赵千里聚扇上写山次韵题","f":"七言律诗","c":["翠水丹山气旁礴，几叠香痕经手握。","何年破镜飞上天，吴淞水剪并刀薄。","江南宝绘多遗馀，王孙不归恨蘼芜。","蘼芜消歇秋风起，班姬为我歌乌乌。"]},{"t":"王时敏听雪斋","f":"七言古诗","c":["顽寒赑屃河流澌，银涛铁骑交奔驰。","珑玲淅簌瓦沟满，坐窗已有幽人知。","东家暖客红醅凝，嘈杂新声迷听瑩。","后园压折万琅玕，雪多政自无人听。","我时空山夜寂寥，风篁雪窦筛琼瑶。","希声疏越不可尽，鸣球戛击如闻韶。","忆昔斋居困学翁，大书听雪烦楚龚。","百年胜事将无同，不传师旷传王恭。","鹤氅明朝行雪里，须辨龙头煎雪水。","床下何人闻斗蚁，唤起春雷来洗耳。"]},{"t":"用韵送净月上人","f":"七言古诗","c":["阴崖颠风无时兴，篁竹偃地虎昼行。","斲冰积雪卧空谷，春至唯闻禽鸟鸣。","华阳南便洞窗小，香烟西放蛾眉道。","神僧问讯破孤寂，把臂入林一倾倒。","帕头蒙寒驴背驮，泥滑稳于杯渡波。","寄谢少年王敬和，独行其如法汰何？"]},{"t":"效隐居拟古乐府寒夜愁","f":"楚辞体","c":["夜寒生，群兽惊，寂兮寥兮栖遁情。","阴宫漫漫落叶平，冈头霜月弄微明。","寒漏涩，寒弦紧。","愁肠结，愁语尽。","人生异木石，思来谁能忍。"]},{"t":"次韵率性来山人见贻之作","f":"曲","c":["南峰后，灵石前，岚霞茜绚争春妍。","贫家客来净扫地，亦有一瓶红杜鹃。","东坡七过山南坞，山人能记坡翁语。","君方骑马听朝鸡，为我入林来听雨。","雨声吹断听松声，怪石长松为友生。","怜君慰我支离者，不饮向人空复情。","我如病马离群去，君如伯乐能相顾。","羊群好在金华山，梦里相逢犹识路。"]},{"t":"早春对雨杂言","f":"七言古诗","c":["寒谷望春如望赦，雨雨风风恶相嚇。","床头败絮未尝温，石上瘦花浑欲谢。","三时尽辨禽鸟鸣，合涧助为风水声。","白水田头漫无路，老稚种麦已青青。","朝晴独见扶犁叟，人生合作无犁耦。","不须识字只耕田，酒杯也到扶犁手。"]},{"t":"次韵段推官观潮","f":"七言律诗","c":["雪涛卷入白螺杯，云梦吞将滟滪堆。","陈马直从天汉落，飓风先自海门来。","青山一向开银壁，黄伞中央立露台。","好在画图留壮观，江头白首不堪回。"]},{"t":"赠纽怜大监","f":"七言律诗","c":["论卷聚书三十万，锦江江上数连艘。","追还教授文翁学，重叹徵求使者劳。","石室谈经修俎豆，草堂迎诏树旂旄。","也知后世扬雄在，献赋为郎愧尔曹。"]},{"t":"老学斋书怀寄京师故人","f":"七言律诗","c":["手种群松数尺围，草深南涧客来稀。","一经断送垂垂老，万事安排念念非。","晨待樵苏才蓐食，凉惊络纬尚絺衣。","蓬莱坊里清宵月，也到山家白板扉。"]},{"t":"晨兴","f":"七言律诗","c":["聊与梅枝说岁穷，真成古木共衰翁。","百年勋业何烦尔，一世云山不负公。","寒梦渐消窗影上，春容已在雨声中。","晨兴陡觉诗神王，未放韶华角长雄。"]},{"t":"次韵虞公和断江和尚种松","f":"七言律诗","c":["松下微吟惬病悰，支离潦倒似支公。","顶因巢鹤翻成结，心为依禅毕竟空。","陆子坛前春古淡，葛洪井上雨青葱。","茯苓乞与杨员外，谁复缄诗过浙东。"]},{"t":"游华藏寺","f":"七言律诗","c":["湖上乱峰如髻鬟，湖边才子驻春鞍。","霜馀鹦鹉沙汀浅，日落麒麟墓道寒。","古壁风篁无尽意，清尊云海有馀欢。","远游未羡鸱夷子，直向飞仙乞羽翰。"]},{"t":"春溪晓渡","f":"七言律诗","c":["怪底朝来云气升，雨晴洗遍碧碐磳。","山腰行李去未远，谷口人家呼渡应。","彷佛箫台凌凤吹，安排春水理鱼罾。","卧游已惬平生志，深负床头六尺藤。"]},{"t":"云林席间怀铁笛简草堂","f":"七言律诗","c":["花朝无花也可怜，桃李矜持不作妍。","烂听雨声眠白昼，梦乘艇子上青天。","閒居尚庶浮云志，老病难趋卜夜筵。","绛帐先生惟寂寞，后堂自理琵琶弦。"]},{"t":"丹阳道中观稼","f":"七言律诗","c":["行遍山东黄叶村，纵横草路细难分。","荒鸡户暗蟏蛸月，落雁天黏䆉稏云。","下泽车傍悬酒榼，延陵词畔读碑文。","空山更觅牛羊径，入兽依然不乱群。"]},{"t":"邓学可留谷城戴尧文许雪中书寄二友","f":"七言律诗","c":["钩帘坐对西山雪，菌阁前头正向阳。","剡水当时元有戴，谷城今日可无张。","披云松树鳞鳞湿，瞰屋山泉角角方。","染就绿霞春帖子，不妨青鸟便衔将。"]},{"t":"赋西塞山送赵季文湖州学录","f":"七言律诗","c":["往来苕霅旧山川，流水桃花思杳然。","溪女浣纱春雨后，仙人把钓夕阳边。","渔歌未用朝廷觅，惠政先由隐逸传。","不信青衫涴尘土，水晶宫里住三千。"]},{"t":"风雨近寒食未已","f":"七言律诗","c":["一榻清寒恋旧毡，无言桃李不成妍。","柳长渐碍螭头舫，雨重浑迷卵色天。","谁向侯家分赐烛，自依丹井食新泉。","海南上巳才登冢，忍待晴泥扫墓田。"]},{"t":"和马伯庸御史春游","f":"七言律诗","c":["山巾垫角雨仍斜，岁岁春风换鬓华。","湖口水香鱼在藻，江南食冷客思家。","鹫峰扫石翻经叶，龙洞分符调井花。","游骑却归城郭暮，醉红犹带脸文霞。"]},{"t":"广陵有寄璚花诗丐余次韵","f":"七言律诗","c":["未信人间日易斜，携春来问列仙家。","情知后土无双树，迷杀江都是此花。","芍药谩吟红茧粟，璚儿从眄玉兰芽。","一壶能共樊川老，醉写乌丝侧帽纱。"]},{"t":"自笑","f":"七言律诗","c":["自笑摧颓如病鹤，羽衣仍复会婆娑。","已裁斑竹将扶老，更剪蟠枝作养和。","骤雨欲来移蚁穴，落花多罢分蜂窠。","裹头多上春官老，不道丘园自一科。"]},{"t":"送朱伯贤茂才之金陵","f":"七言律诗","c":["句容山邑长官清，此日况逢贤友生。","案牍劳人烦慰藉，风尘为客话经行。","宽裁白苧游萧寺，近觅青骡过冶城。","能赋钟英怀古昔，一时骢马尽知名。"]},{"t":"题陈琳摹董源渔乐图","f":"七言律诗","c":["小笔谁临北苑图，兰亭玉枕最难模。","连峰秀树□□□，□□荒云远欲无。","泊向小孤缘爱石，望从青草别名湖。","□□□□如相借，暂卸南风十幅蒲。"]},{"t":"孤山即事","f":"七言律诗","c":["笑抚湖山迹易陈，先贤祠宇一番新。","玉鱼蔓草多无主，白鹄秋天迥有神。","曲港穿冲花外骑，赤阑扶约水边人。","冈头□□枯梅蘖，独是先生肺腑亲。"]},{"t":"素华台","f":"七言律诗","c":["素华台榭压昆丘，况近仙家十二楼。","白里深蟠龙虎气，空中遥接凤凰游。","琉璃研水偏盛月，云母屏风不隔秋。","姑射山中有冰雪，神人愿与国同休。"]},{"t":"六月六日步过白莲峰眠食尽日而回","f":"七言律诗","c":["沥沥阶除走暗泉，入厨新溜动厨烟。","早来燕坐斋中饭，梦在山光寺里眠。","石脚尽盘千个竹，树头未动一声蝉。","此中长日谁为伴？","海岳庵诗在枕边。"]},{"t":"猿臂笛","f":"七言律诗","c":["三峡家山已隔生，一枝玉骨尚堪横。","攀援远似穿云曲，吟啸高于喷竹声。","栗叶霜黄天竺梦，梅花春老玉关情。","伶伦且为相娱乐，谁问将军善射名。"]},{"t":"夏商隐还京师","f":"七言律诗","c":["扈跸行营三十载，王门不肯曳长裾。","閒从角里先生饮，与说圯桥父老书。","花外飞丸红叱拨，月中采药玉蟾蜍。","残骸尚有刀圭分，会向南山访弊庐。"]},{"t":"和率性大涤十咏 其一 云根石","f":"七言律诗","c":["石色斑斑野鹿胎，石身浑裹夜明苔。","直将瑞气穿龙洞，不比游尘汗马嵬。","岩下松枝同不朽，月中鹤驾合频来。","君看怪石英雄坐，寂寞于今卧草莱。"]},{"t":"和率性大涤十咏 其二 龙洞","f":"七言律诗","c":["怪石蜿蜒驱不动，自从开辟镇重坤。","雨声多在南山殷，云气都令白昼昏。","百尺潜虬窥海眼，一杯流水浸松根。","有时急□天符下，故遣灵人夜叩阍。"]},{"t":"和率性大涤十咏 其三 凤洞","f":"七言律诗","c":["第几峰前苍玉洞，何年于此凤求皇。","梧枝宿久毛皆变，竹实餐多髓亦香。","露湿紫苔春似锦，月明丹穴夜生光。","我亦鹓行旧俦侣，云中有路共回翔。"]},{"t":"和率性大涤十咏 其四 翠蛟亭","f":"七言律诗","c":["谁见苍龙劈石开，此峰元自胜飞来。","阑干截断山头雨，赑屃翻将地底雷。","寒甚祇疑云是雪，霜馀每恨叶成堆。","坡仙独对无言说，惭愧搜诗日几回。"]},{"t":"祀五先生景行莫君为遨头诗以记之","f":"七言律诗","c":["洛中诸老今谁识，饮少年高听细论。","百五日前花送雨，十三楼下水侵门。","岭霞栖向仇池穴，春鸟啼将蜀客魂。","方外归来羞秃鬓，也容乡社割鸡豚。"]},{"t":"金陵僧来闻笑隐住持事繁风雨有怀","f":"七言律诗","c":["忆曾共坐翻经石，语我松华压酒方。","一自宜城居辅国，几时天竺话连床。","栖栖春草元桑楚，历历风铃替戾冈。","乞得江东今夕雨，与君聊洗梦中忙。"]},{"t":"闰三月三日北山看花不与盟","f":"七言律诗","c":["应笑黄花厄闰时，后三仍复负芳期。","老无刘几簪花分，閒有陶潜止酒诗。","谷雨林中先紫笋，郁罡山口足黄鹂。","韩湘自倩奴星去，袖得瑶台第一枝。"]},{"t":"形影","f":"七言律诗","c":["形影胡为乐此留，山川映发思绸缪。","歌长杯酒毋多酌，世短何人第一流。","弟子受经犹北面，樵青分屋自西头。","下方误识金银气，直倚崆峒一剑秋。"]},{"t":"王若水梨花山鹊","f":"五言绝句","c":["山鹊语查查，惊飞白雪花。","清明人载酒，寒食客思家。"]},{"t":"芍药白兔图","f":"五言绝句","c":["妥帖红云朵，迷离玉兔儿。","扬州行乐地，惆怅鬓成丝。"]},{"t":"绝句","f":"曲","c":["二山环合一水，中有老木参天。","不著幽人草阁，谁收无限云烟。"]},{"t":"腊尽","f":"七言绝句","c":["小雪初晴腊尽时，无穷梅柳怨开迟。","人间不觉春来早，只有吾家布被知。"]},{"t":"山中客夜","f":"七言绝句","c":["鞍马南州五日程，岂知物外有茅亭。","尘埃暑困人如醉，月露夜凉天亦醒。"]},{"t":"明德游仙词十首用天柱山传来依韵继作云林道气者观之亦足自拔于埃壒矣 其一","f":"七言绝句","c":["白玉之盘沧海东，苍苍下视远如空。","请看端正山河影，不满坳堂杯水中。"]},{"t":"明德游仙词十首用天柱山传来依韵继作云林道气者观之亦足自拔于埃壒矣 其二","f":"七言绝句","c":["鸿宝枕函云积叠，芝台炉火暖氤氲。","子能试吃青精饭，我亦聊书白练裙。"]},{"t":"明德游仙词十首用天柱山传来依韵继作云林道气者观之亦足自拔于埃壒矣 其三","f":"七言绝句","c":["夜久扶桑海色分，珠宫望拜赤龙君。","洞庭未省君山在，元是昆仑一朵云。"]},{"t":"明德游仙词十首用天柱山传来依韵继作云林道气者观之亦足自拔于埃壒矣 其四","f":"七言绝句","c":["藤萝石上寻长迹，金粟图中见小身。","抖擞几重衣裓看，情知不□散花人。"]},{"t":"明德游仙词十首用天柱山传来依韵继作云林道气者观之亦足自拔于埃壒矣 其五","f":"七言绝句","c":["庞见《霓裳》舞广庭，罢看三十九章经。","道人腰著金鸦嘴，自向松根洗茯苓。"]},{"t":"明德游仙词十首用天柱山传来依韵继作云林道气者观之亦足自拔于埃壒矣 其六","f":"七言绝句","c":["右股清池足沤麻，池中肥水是松花。","早知魏帝一丸药，肯信东门五色瓜。"]},{"t":"明德游仙词十首用天柱山传来依韵继作云林道气者观之亦足自拔于埃壒矣 其七","f":"七言绝句","c":["耻作深山服食仙，伐毛洗髓故依然。","木兰坠露研朱写，只写南华《秋水》篇。"]},{"t":"明德游仙词十首用天柱山传来依韵继作云林道气者观之亦足自拔于埃壒矣 其八","f":"七言绝句","c":["脚底琴生三尺鲤，袖中阿母一双桃。","别时身动凌波袜，烂月如银照夜涛。"]},{"t":"明德游仙词十首用天柱山传来依韵继作云林道气者观之亦足自拔于埃壒矣 其九","f":"七言绝句","c":["眼中自小薄蓬瀛，日日双飞下始青。","□□明窗尘仿佛，定知草创大丹成。"]},{"t":"明德游仙词十首用天柱山传来依韵继作云林道气者观之亦足自拔于埃壒矣 其十","f":"七言绝句","c":["玉格金科自有期，赤城何待远寻师。","壁梭也解为龙去，樵斧如何只看棋。"]},{"t":"听琴图","f":"七言绝句","c":["袅烟石壁对孤桐，与和长松瑟瑟风。","不为野夫清两耳，为君留目送飞鸿。"]},{"t":"史局先生示以季境□□赠行卷辄题一绝卷锦","f":"七言绝句","c":["校书苦借青藜杖，下马笑拈金屈卮。","好是淮南师弟子，钱唐相见落花时。"]},{"t":"三香图","f":"七言绝句","c":["凌波仙子尘生袜，空谷佳人玉鍊容。","不奈天寒风露早，日高犹傍锦熏笼。"]},{"t":"绝句","f":"七言绝句","c":["白足过桥三峡雪，苍头吹笛满林风。","狂花也有凌霄意，飞上松颠烂熳红。"]},{"t":"题理妆士女","f":"七言绝句","c":["谁见新妆出绣帏，辛夷花下六铢衣。","莫教蜂蝶知踪迹，閒与邻娃斗草归。"]},{"t":"玄览堂绝句","f":"七言绝句","c":["帘栊低亚小梅枝，快雪时晴绿满池。","铃索不摇鹦鹉睡，客来假寐亦多时。"]},{"t":"题张溪云画钩勒竹","f":"七言绝句","c":["为爱风篁手自摹，不烦把烛倩官奴。","须当白战筼筜谷，羞杀江南没骨图。"]},{"t":"金人出猎图","f":"七言绝句","c":["小队鸣笳晓出围，地椒狼藉兽应肥。","上皇久厌猩羊粉，故遣萧郎击豕归。"]},{"t":"灵岩寺","f":"七言绝句","c":["我欲搜林觅砚材，谁将奇石半岩栽。","胸中故有涵空阁，好借君王避暑来。"]},{"t":"次韵怀友","f":"七言绝句","c":["秋衣零落补纫多，剪尽西兴半亩荷。","寒到故人殊未到，不消湖上雁来过。"]},{"t":"春菜","f":"七言绝句","c":["土甲离离宿雨痕，畦蔬小摘当盘飧。","红绫饼餤残牙齿，合向岩头嚼菜根。"]},{"t":"春药","f":"七言绝句","c":["紫甲红牙玉满阑，时分花雨润斑斑。","茯苓乍可来归笼，远志从来不出山。"]},{"t":"登善精舍葺治苟完七小诗以写予怀 其一","f":"七言绝句","c":["故山破屋谁来补，辛苦经营拾燕泥。","几树桃花相送老，不消更著子规啼。"]},{"t":"登善精舍葺治苟完七小诗以写予怀 其二","f":"七言绝句","c":["涧中采石重铺径，坡上移花小筑墩。","深结云岚为保障，剩培松竹当儿孙。"]},{"t":"登善精舍葺治苟完七小诗以写予怀 其三","f":"七言绝句","c":["梓柳都移五十栽，稚松千个绿毰毸。","旁人莫笑千年计，万一他时化鹤来。"]},{"t":"登善精舍葺治苟完七小诗以写予怀 其四","f":"七言绝句","c":["玉钩桥水如凝碧，才过床头写瀑雷。","恰是东风太薄劣，逆流花片出墙来。"]},{"t":"云林画","f":"七言绝句","c":["望见龙山第一峰，一峰一面水如弓。","水边亭子无人到，犹有前时蹑屐踪。"]},{"t":"李商隐学仙","f":"七言绝句","c":["谁云有分不关情，沦谪千年为底名。","消得权儿羊浣布，诗中唯数玉溪生。"]},{"t":"京师答薛玄卿","f":"七言绝句","c":["重重城阙乱烟花，只拟将身乞酒家。","试听御沟冰下水，与君持底驻年华。"]},{"t":"三衢道中三首 其一","f":"七言绝句","c":["大溪中道放船流，船压山光泻碧油。","三百里滩攲枕过，买鱼酾酒下严州。"]},{"t":"三衢道中三首 其二","f":"七言绝句","c":["东风恶剧雨飞花，被底春寒水涨沙。","兰茝溪香小回首，一峰晴雪是金华。"]},{"t":"三衢道中三首 其三","f":"七言绝句","c":["界道飞流山翠重，杜鹃无语杜鹃红。","归人一舸贪新水，浑堕丹青便面中。"]},{"t":"灯花联句","f":"五言古诗","c":["星阁迎寒閟，霜钟动夜摐。","酒深燔朮火，漏下续兰釭。","寸草荧芝小，丹葩瑞带双。","金枝交婉娈，银粟乱鬃鬞。","蜡结飞蛾笑，膏融吐凤愯。","汞珠光透镜，火齐幻垂幢。","的的煇青琐，淫淫飐玉缸。","烛龙擎紫盖，翘燕缀红䝄。","邻眼书窥隙，仙眉墨晕窗。","狂吟心蕊发，喜听足音跫。","折堲风吹座，钩帘月堕江。","青藜如见遇，挥手出纷厖。"]},{"t":"集太白语酬僧净月","f":"曲","c":["主人碧岩里，为余话幽栖。","真诀自从茅氏得，风流还与远公齐。","满堂空翠如可扫，而君解来一何好。","白玉麈尾谈重玄，琉璃砚水常枯槁。","苍苍云松，拂彼白石。","世人闻此皆掉头，就中与君心莫逆。","袖拂紫烟去，空中闻天鸡。","借问苏耽鹤，早晚向江西。"]},{"t":"集王摩诘书语六言二首 其一","f":"曲","c":["寒犬吠声如豹，夜春相应疏钟。","华子冈头清月，照人独坐山中。"]},{"t":"集王摩诘书语六言二首 其二","f":"曲","c":["夜深僮仆静默，月明辋水沦涟。","独与山僧饭讫，寒林远火初然。"]},{"t":"元统元年冬十一月句曲外史菌山巢居成制十小诗以自见录呈华阳隐居资一捧腹 其一","f":"七言绝句","c":["崇元馆主在齐梁，乃有元之吴郡张。","相望八百四十载，我居鹤台如故乡。"]},{"t":"元统元年冬十一月句曲外史菌山巢居成制十小诗以自见录呈华阳隐居资一捧腹 其二","f":"七言绝句","c":["望见飞檐松杪花，下盘阴洞石聱牙。","老樵迷路疑相问，若个江东道士家。"]},{"t":"元统元年冬十一月句曲外史菌山巢居成制十小诗以自见录呈华阳隐居资一捧腹 其三","f":"七言绝句","c":["风水所言唯理气，眼明此术未全疏。","景纯解道游仙句，信是青囊有异书。"]},{"t":"元统元年冬十一月句曲外史菌山巢居成制十小诗以自见录呈华阳隐居资一捧腹 其四","f":"七言绝句","c":["缥缈洞庭连白云，绿橘黄柑能见分。","昨日扁舟寻好事，明年处士比封君。"]},{"t":"元统元年冬十一月句曲外史菌山巢居成制十小诗以自见录呈华阳隐居资一捧腹 其五","f":"七言绝句","c":["谷中仅仅一庵住，坛上累累白石陈。","杖随流水过邻舍，席与长松分主宾。"]},{"t":"元统元年冬十一月句曲外史菌山巢居成制十小诗以自见录呈华阳隐居资一捧腹 其六","f":"七言绝句","c":["但倚茅君为座主，从称外史作官衔。","道家六经发愿写，深向石头藏一函。"]},{"t":"元统元年冬十一月句曲外史菌山巢居成制十小诗以自见录呈华阳隐居资一捧腹 其七","f":"七言绝句","c":["屋壁置书碑版多，雄虹光怪凤凰阿。","看到空山十日雪，灶突无烟奈尔何。"]},{"t":"元统元年冬十一月句曲外史菌山巢居成制十小诗以自见录呈华阳隐居资一捧腹 其八","f":"七言绝句","c":["肯借山中步障锦，与作天下庇寒裘。","三尺窗棂万株木，不怕霜寒到上头。"]},{"t":"元统元年冬十一月句曲外史菌山巢居成制十小诗以自见录呈华阳隐居资一捧腹 其九","f":"七言绝句","c":["只有天公终可倚，我作巢居名倚天。","未必高虚无事业，负日读书兼打眠。"]},{"t":"元统元年冬十一月句曲外史菌山巢居成制十小诗以自见录呈华阳隐居资一捧腹 其十","f":"七言绝句","c":["龙虎山中薛玄子，璚林筑台诗亦工。","应接菌山聊尔耳，非关千里事同风。"]},{"t":"道言","f":"五言古诗","c":["造物于我厚，一切使我薄。","瓶中有储粟，持此卧云壑。","弊衣取苟完，得味在藜藿。","花鸟予友于，尊酒不独酌。","床头堆故书，败履置床脚。","未尝身没溺，何与世浊恶。","正如散马牛，不识穿与络。","异时老髑髅，会有南面乐。"]},{"t":"九月风雨清斋","f":"五言古诗","c":["中林授衣节，寒气早已集。","牖户洎裘褐，凡百缺治葺。","穷居昧时序，颇讶光景急。","丛篁助幽翳，漾濑发空寂。","水禽穿屋过，岩树排檐入。","陶尊既尘渍，墨突亦雨立。","遐思把菊咏，端处掬溜室。","空言非药饵，殆不废九日。"]},{"t":"涧阿对雨二首卷二改。按张雨另有涧阿晚兴诗可證。】 其一","f":"五言古诗","c":["山云油然作，山雨来不缓。","既沾灵石坞，遂洒寒栖馆。","落水遽如许，众草行复烂。","有酒不堪酌，无物堪把玩。","与闻季长笛，宁从中散锻。","代谢夫何如，徒为白首叹。"]},{"t":"涧阿对雨二首卷二改。按张雨另有涧阿晚兴诗可證。】 其二","f":"五言律诗","c":["步归灵涧幽，泥染居士屩。","不知岚雨深，稍怯布衣薄。","拂床次群帙，扫径堆脱箨。","清坐亦偶然，吾非慕仙爵。"]},{"t":"延陵公承庆堂诗","f":"曲","c":["大江苍苍兀龙虎，辅元之家百神頫。","望拜受釐若稽古，上清真人阅众甫。","新宫洁斋导天语，纷云郁霞错承宇。","虚皇穆然阳卫武，左飙右欻降軨羽。","县钟镗镗迅击鼓，赫金蔡服赭朱户。","双珠月明带宝璐，挟以流黄玉■（木昙）具。","既竣大礼私事举，吉日宗族奉爵俎。","青紫系地簪绶组，魏张代剑新捧土。","饶国开观治宿莽，报君亲师物咸睹。","抚己一念或未溥，西壁考书玄范府。","寒冰层阴发春煦，日若休明沐仁雨。","道德大非方仙五，月佩六印非适取。","持旌召趣迹旁午，下土滓?宁久处。","天关会规足蹈矩，愿天愿地多黍稌。","毕志万年奉明主，小史作书孰敢侮。","吁嗟厚德番之祖。"]},{"t":"句","f":"七言古诗","c":["家藏逸少笼鹅字，门系龟蒙放鸭船。"]},{"t":"句","f":"七言古诗","c":["风沙不惮五千里，将身跳入仙人壶。"]},{"t":"双调・殿前欢杨廉夫席上有赠","f":"曲","c":["小吴娃，玉盘仙掌载春霞。","后堂绛帐重帘下，谁理琵琶？香山处士家，玉局仙人画，一刻春无价。","老夫醉也，乌帽琼华。"]},{"t":"双调・水仙子","f":"曲","c":["归来重整旧生涯，潇洒柴桑处士家。","草庵儿不用高和大，会清标岂在繁华？纸糊窗，柏木榻。","挂一幅单条画，供一枝得意花，自烧香童子煎茶。"]}]};